globalThis.TF_PHRASE_DATA=globalThis.TF_PHRASE_DATA||{};globalThis.TF_PHRASE_DATA["quotes"]={"schemaVersion":1,"collection":"quotes","title":"Danh ngôn tiếng Anh","count":300,"items":[{"id":"qte-0001","text":"“To be, or not to be: that is the question.”","vi":"Suy ngẫm về sự tồn tại và lựa chọn.","ex":"The line “To be, or not to be: that is the question” comes from Hamlet.","exVi":"Câu “Tồn tại hay không tồn tại: đó là câu hỏi” trích từ vở Hamlet.","src":"William Shakespeare · Hamlet","level":"general","topics":["Lựa chọn","Suy ngẫm"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false,"note":"Di trú nguyên trạng từ bộ cũ; nguồn chưa được kiểm chứng độc lập."},{"id":"qte-0002","text":"“Brevity is the soul of wit.”","vi":"Sự ngắn gọn là cốt lõi của trí tuệ và sự hóm hỉnh.","ex":"In a concise presentation, brevity is the soul of wit.","exVi":"Trong một bài thuyết trình súc tích, ngắn gọn là cốt lõi của sự hóm hỉnh.","src":"William Shakespeare · Hamlet","level":"general","topics":["Giao tiếp","Văn phong"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false,"note":"Di trú nguyên trạng từ bộ cũ; nguồn chưa được kiểm chứng độc lập."},{"id":"qte-0003","text":"“All the world’s a stage.”","vi":"Cuộc đời được ví như một sân khấu, nơi con người đảm nhận nhiều vai trò.","ex":"The poem begins with the famous line, “All the world’s a stage.”","exVi":"Bài thơ mở đầu bằng câu nổi tiếng: “Cả thế gian là một sân khấu.”","src":"William Shakespeare · As You Like It","level":"general","topics":["Đời sống","Quan hệ"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false,"note":"Di trú nguyên trạng từ bộ cũ; nguồn chưa được kiểm chứng độc lập."},{"id":"qte-0004","text":"“There is nothing either good or bad, but thinking makes it so.”","vi":"Cách nhìn nhận có thể ảnh hưởng đến việc ta đánh giá một sự việc.","ex":"Hamlet reflects that there is nothing either good or bad, but thinking makes it so.","exVi":"Hamlet suy ngẫm rằng không có gì tự nó tốt hay xấu; chính suy nghĩ khiến nó thành như vậy.","src":"William Shakespeare · Hamlet","level":"general","topics":["Tư duy","Cảm xúc"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false,"note":"Di trú nguyên trạng từ bộ cũ; nguồn chưa được kiểm chứng độc lập."},{"id":"qte-0005","text":"“No man is an island.”","vi":"Không ai hoàn toàn tách biệt; con người cần gắn kết với nhau.","ex":"The essay reminds us that no man is an island.","exVi":"Bài luận nhắc chúng ta rằng không ai là một hòn đảo biệt lập.","src":"John Donne · Meditation XVII","level":"general","topics":["Quan hệ"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false,"note":"Di trú nguyên trạng từ bộ cũ; nguồn chưa được kiểm chứng độc lập."},{"id":"qte-0006","text":"“Well done is better than well said.”","vi":"Làm tốt có giá trị hơn chỉ nói hay.","ex":"Her work reflects the idea that well done is better than well said.","exVi":"Công việc của cô thể hiện quan niệm rằng làm tốt có giá trị hơn chỉ nói hay.","src":"Benjamin Franklin · Poor Richard’s Almanack","level":"general","topics":["Hành động","Công việc"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false,"note":"Di trú nguyên trạng từ bộ cũ; nguồn chưa được kiểm chứng độc lập."},{"id":"qte-0007","text":"“Lost time is never found again.”","vi":"Thời gian đã mất thì không thể lấy lại.","ex":"The reminder “Lost time is never found again” encourages me to plan carefully.","exVi":"Lời nhắc “Thời gian đã mất thì không thể lấy lại” khuyến khích tôi lên kế hoạch cẩn thận.","src":"Benjamin Franklin · Poor Richard’s Almanack","level":"general","topics":["Thời gian"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false,"note":"Di trú nguyên trạng từ bộ cũ; nguồn chưa được kiểm chứng độc lập."},{"id":"qte-0008","text":"“Our doubts are traitors, and make us lose the good we oft might win, by fearing to attempt.”","vi":"Sự nghi ngờ có thể khiến ta bỏ lỡ điều tốt đẹp vì sợ thử sức.","ex":"The line “Our doubts are traitors” encourages the character to act despite uncertainty.","exVi":"Câu “Sự nghi ngờ là kẻ phản bội” khuyến khích nhân vật hành động dù còn chưa chắc chắn.","src":"William Shakespeare · Measure for Measure","level":"general","topics":["Cảm xúc","Cơ hội"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false,"note":"Di trú nguyên trạng từ bộ cũ; nguồn chưa được kiểm chứng độc lập."},{"id":"qte-0009","text":"“The better part of valour is discretion.”","vi":"Sự thận trọng đôi khi là phần khôn ngoan nhất của lòng dũng cảm.","ex":"He decided not to take an unnecessary risk, remembering that the better part of valour is discretion.","exVi":"Anh quyết định không mạo hiểm vô ích, nhớ rằng sự thận trọng đôi khi là phần khôn ngoan nhất của lòng dũng cảm.","src":"William Shakespeare · Henry IV, Part 1","level":"general","topics":["Quyết định"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false,"note":"Di trú nguyên trạng từ bộ cũ; nguồn chưa được kiểm chứng độc lập."},{"id":"qte-0010","text":"“The journey of a thousand miles begins with a single step.”","vi":"Hành trình dài bắt đầu từ bước đi đầu tiên.","ex":"Learning a language takes time; the journey of a thousand miles begins with a single step.","exVi":"Học một ngôn ngữ cần thời gian; hành trình ngàn dặm bắt đầu từ một bước chân.","src":"Laozi · Tao Te Ching, traditional translation","level":"general","topics":["Kiên trì","Học tập"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false,"note":"Di trú nguyên trạng từ bộ cũ; nguồn chưa được kiểm chứng độc lập."},{"id":"qte-0011","text":"“It is a truth universally acknowledged.”","vi":"Một nhận định được xem là ai cũng thừa nhận; thường dùng với sắc thái châm biếm.","ex":"The essay opens with the line, “It is a truth universally acknowledged.”","exVi":"Bài luận mở đầu bằng câu: “Đó là một sự thật được mọi người thừa nhận.”","src":"Jane Austen · Pride and Prejudice","level":"general","topics":["Văn học","Tư duy"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false,"note":"Di trú nguyên trạng từ bộ cũ; nguồn chưa được kiểm chứng độc lập."},{"id":"qte-0012","text":"“All that glisters is not gold.”","vi":"Vẻ ngoài lấp lánh không đảm bảo giá trị thật.","ex":"The old saying warns us that all that glisters is not gold.","exVi":"Câu nói xưa nhắc ta rằng vẻ ngoài lấp lánh không đồng nghĩa với giá trị thật.","src":"William Shakespeare · The Merchant of Venice","level":"general","topics":["Giá trị sống"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false,"note":"Di trú nguyên trạng từ bộ cũ; nguồn chưa được kiểm chứng độc lập."},{"id":"qte-0013","text":"“Curiouser and curiouser!”","vi":"Thật ngày càng kỳ lạ; thể hiện sự ngạc nhiên khi điều lạ tiếp diễn.","ex":"“Curiouser and curiouser!” she exclaimed as the room began to shrink.","exVi":"“Thật ngày càng kỳ lạ!” cô kêu lên khi căn phòng bắt đầu thu nhỏ.","src":"Lewis Carroll · Alice’s Adventures in Wonderland","level":"general","topics":["Cảm xúc","Tò mò"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false,"note":"Di trú nguyên trạng từ bộ cũ; nguồn chưa được kiểm chứng độc lập."},{"id":"qte-0014","text":"“It was the best of times, it was the worst of times.”","vi":"Một thời kỳ vừa có điều tốt đẹp vừa có điều tồi tệ.","ex":"The opening captures the contrast: it was the best of times, it was the worst of times.","exVi":"Câu mở đầu diễn tả sự đối lập: đó là thời kỳ tốt đẹp nhất, cũng là tồi tệ nhất.","src":"Charles Dickens · A Tale of Two Cities","level":"general","topics":["Lịch sử","Đời sống"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false,"note":"Di trú nguyên trạng từ bộ cũ; nguồn chưa được kiểm chứng độc lập."},{"id":"qte-0015","text":"“To err is human; to forgive, divine.”","vi":"Mắc lỗi là bản tính con người; tha thứ là điều cao đẹp.","ex":"The poem suggests that to err is human; to forgive, divine.","exVi":"Bài thơ gợi nhắc rằng mắc lỗi là bản tính con người, còn tha thứ là điều cao đẹp.","src":"Alexander Pope · An Essay on Criticism","level":"general","topics":["Giá trị sống"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false,"note":"Di trú nguyên trạng từ bộ cũ; nguồn chưa được kiểm chứng độc lập."},{"id":"qte-0016","text":"“The proper study of mankind is man.”","vi":"Con người và bản tính con người là đối tượng đáng để tìm hiểu.","ex":"The essay turns to society because the proper study of mankind is man.","exVi":"Bài luận hướng đến xã hội vì con người là đối tượng đáng để tìm hiểu.","src":"Alexander Pope · An Essay on Man","level":"general","topics":["Học tập","Con người"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false,"note":"Di trú nguyên trạng từ bộ cũ; nguồn chưa được kiểm chứng độc lập."},{"id":"qte-0017","text":"“There is no charm equal to tenderness of heart.”","vi":"Không gì đáng quý bằng một trái tim dịu dàng.","ex":"Her kindness reflects the idea that there is no charm equal to tenderness of heart.","exVi":"Lòng tốt của cô thể hiện rằng không gì đáng quý bằng một trái tim dịu dàng.","src":"Jane Austen · Emma","level":"general","topics":["Quan hệ","Cảm xúc"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false,"note":"Di trú nguyên trạng từ bộ cũ; nguồn chưa được kiểm chứng độc lập."},{"id":"qte-0018","text":"“The truth will set you free.”","vi":"Sự thật có thể giải phóng con người khỏi dối trá và sợ hãi.","ex":"He decided to speak honestly, believing that the truth will set you free.","exVi":"Anh quyết định thành thật vì tin rằng sự thật có thể giải phóng con người.","src":"The Bible · John 8:32","level":"general","topics":["Giá trị sống"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false,"note":"Di trú nguyên trạng từ bộ cũ; nguồn chưa được kiểm chứng độc lập."},{"id":"qte-0019","text":"“There is nothing like staying at home for real comfort.”","vi":"Không gì đem lại cảm giác dễ chịu như được ở nhà.","ex":"After a long trip, there is nothing like staying at home for real comfort.","exVi":"Sau chuyến đi dài, không gì dễ chịu bằng được ở nhà.","src":"Jane Austen · Emma","level":"general","topics":["Gia đình","Nhà cửa"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false,"note":"Di trú nguyên trạng từ bộ cũ; nguồn chưa được kiểm chứng độc lập."},{"id":"qte-0020","text":"“The old order changeth, yielding place to new.”","vi":"Trật tự cũ thay đổi và nhường chỗ cho điều mới.","ex":"The new policy reflects the thought that the old order changeth, yielding place to new.","exVi":"Chính sách mới gợi nhắc rằng trật tự cũ thay đổi và nhường chỗ cho điều mới.","src":"Alfred, Lord Tennyson · The Passing of Arthur","level":"general","topics":["Thay đổi","Thời gian"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false,"note":"Di trú nguyên trạng từ bộ cũ; nguồn chưa được kiểm chứng độc lập."},{"id":"qte-0021","text":"Frailty, thy name is woman!","vi":"Hamlet than thở về sự yếu đuối mà chàng cho là gắn với mẹ mình.","ex":"Hamlet laments, “Frailty, thy name is woman!”","exVi":"Hamlet than thở: “Yếu đuối, tên nàng là đàn bà!”","src":"William Shakespeare · Hamlet (Second Quarto, 1604)","level":"general","topics":["Cảm xúc","Quan hệ gia đình"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0022","text":"Give every man thy ear, but few thy voice.","vi":"Hãy lắng nghe nhiều người nhưng chỉ chia sẻ ý kiến một cách chọn lọc.","ex":"Polonius advises, “Give every man thy ear, but few thy voice.”","exVi":"Polonius khuyên: “Hãy lắng nghe mọi người, nhưng chỉ nói với một số ít.”","src":"William Shakespeare · Hamlet (Second Quarto, 1604)","level":"general","topics":["Giao tiếp","Lời khuyên"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0023","text":"Something is rotten in the state of Denmark.","vi":"Có điều gì đó bất ổn trong xã hội hoặc tổ chức đang được nói đến.","ex":"Marcellus warns, “Something is rotten in the state of Denmark.”","exVi":"Marcellus cảnh báo: “Có điều gì đó mục ruỗng trong vương quốc Đan Mạch.”","src":"William Shakespeare · Hamlet (Second Quarto, 1604)","level":"general","topics":["Xã hội","Bất ổn"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0024","text":"One may smile and smile and be a villain.","vi":"Nụ cười bên ngoài không phải lúc nào cũng phản ánh ý định thật.","ex":"Hamlet writes, “One may smile and smile and be a villain.”","exVi":"Hamlet viết: “Một người có thể cứ mỉm cười mà vẫn là kẻ xấu.”","src":"William Shakespeare · Hamlet (Second Quarto, 1604)","level":"general","topics":["Lòng tin","Tính cách"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0025","text":"Though this be madness, yet there is method in ’t.","vi":"Ngay cả điều có vẻ vô lý đôi khi vẫn có logic riêng.","ex":"Polonius muses, “Though this be madness, yet there is method in ’t.”","exVi":"Polonius ngẫm rằng: “Dẫu đây là sự điên rồ, trong đó vẫn có logic.”","src":"William Shakespeare · Hamlet (Second Quarto, 1604)","level":"general","topics":["Tư duy","Quan sát"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0026","text":"Conscience does make cowards of us all.","vi":"Nỗi lo về đúng sai có thể khiến con người chùn bước trước quyết định khó khăn.","ex":"Hamlet observes, “Conscience does make cowards of us all.”","exVi":"Hamlet nhận xét: “Lương tâm quả khiến tất cả chúng ta trở nên nhút nhát.”","src":"William Shakespeare · Hamlet (Second Quarto, 1604)","level":"general","topics":["Đạo đức","Quyết định"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0027","text":"The lady doth protest too much, methinks.","vi":"Sự phủ nhận quá mức có thể khiến người khác nghi ngờ điều được khẳng định.","ex":"The Queen remarks, “The lady doth protest too much, methinks.”","exVi":"Hoàng hậu nhận xét: “Theo ta, người phụ nữ ấy phản đối hơi quá mức.”","src":"William Shakespeare · Hamlet (Second Quarto, 1604)","level":"general","topics":["Giao tiếp","Nghi ngờ"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0028","text":"My words fly up, my thoughts remain below.","vi":"Lời nói thành kính sẽ vô nghĩa nếu suy nghĩ bên trong không chân thành.","ex":"The King admits, “My words fly up, my thoughts remain below.”","exVi":"Nhà vua thú nhận: “Lời ta bay lên, còn tâm tư vẫn ở lại bên dưới.”","src":"William Shakespeare · Hamlet (Second Quarto, 1604)","level":"general","topics":["Sự chân thành","Suy ngẫm"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0029","text":"I must be cruel only to be kind.","vi":"Đôi khi phải nghiêm khắc trước mắt để hướng tới điều tốt hơn về lâu dài.","ex":"Hamlet explains, “I must be cruel only to be kind.”","exVi":"Hamlet giải thích: “Ta phải nghiêm khắc chỉ để có thể tử tế.”","src":"William Shakespeare · Hamlet (Second Quarto, 1604)","level":"general","topics":["Lòng tốt","Quyết định"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0030","text":"How all occasions do inform against me.","vi":"Mọi sự việc dường như đều nhắc Hamlet rằng chàng chưa hành động như cần thiết.","ex":"Hamlet reflects, “How all occasions do inform against me.”","exVi":"Hamlet suy ngẫm: “Mọi sự việc đều khiến ta thấy mình có lỗi.”","src":"William Shakespeare · Hamlet (Second Quarto, 1604)","level":"general","topics":["Tự nhìn nhận","Hành động"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0031","text":"The readiness is all.","vi":"Điều quan trọng là luôn sẵn sàng đón nhận những gì có thể xảy ra.","ex":"He decides, “The readiness is all.”","exVi":"Chàng quyết định: “Điều cốt yếu là sự sẵn sàng.”","src":"William Shakespeare · Hamlet (Second Quarto, 1604)","level":"general","topics":["Chuẩn bị","Thái độ sống"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0032","text":"The rest is silence.","vi":"Sau lời cuối cùng, chỉ còn lại sự im lặng.","ex":"He says, “The rest is silence.”","exVi":"Chàng nói: “Phần còn lại là im lặng.”","src":"William Shakespeare · Hamlet (Second Quarto, 1604)","level":"general","topics":["Im lặng","Kết thúc"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0033","text":"One woe doth tread upon another’s heel.","vi":"Nỗi buồn này nối tiếp nỗi buồn khác.","ex":"The Queen observes, “One woe doth tread upon another’s heel.”","exVi":"Hoàng hậu nhận xét: “Nỗi buồn này giẫm lên gót nỗi buồn khác.”","src":"William Shakespeare · Hamlet (Second Quarto, 1604)","level":"general","topics":["Khó khăn","Cảm xúc"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0034","text":"Things without all remedy should be without regard.","vi":"Điều không thể sửa đổi thì không nên tiếp tục khiến ta bận lòng.","ex":"Lady Macbeth says, “Things without all remedy should be without regard.”","exVi":"Phu nhân Macbeth nói: “Điều không thể cứu vãn thì đừng bận tâm nữa.”","src":"William Shakespeare · Macbeth (First Folio, 1623)","level":"general","topics":["Chấp nhận","Suy ngẫm"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0035","text":"Macbeth does murder sleep.","vi":"Tội lỗi đã cướp đi sự bình yên và giấc ngủ của Macbeth.","ex":"A voice cries, “Macbeth does murder sleep.”","exVi":"Một giọng nói vang lên: “Macbeth đã sát hại giấc ngủ.”","src":"William Shakespeare · Macbeth (First Folio, 1623)","level":"general","topics":["Tội lỗi","Giấc ngủ"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0036","text":"Tomorrow and tomorrow and tomorrow.","vi":"Ngày mai cứ nối tiếp ngày mai, gợi cảm giác thời gian trôi đều và lặp lại.","ex":"Macbeth repeats, “Tomorrow and tomorrow and tomorrow.”","exVi":"Macbeth lặp lại: “Ngày mai, rồi ngày mai, rồi lại ngày mai.”","src":"William Shakespeare · Macbeth (First Folio, 1623)","level":"general","topics":["Thời gian","Đời sống"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0037","text":"Look like the innocent flower, but be the serpent under ’t.","vi":"Hãy tỏ vẻ vô hại trong khi che giấu ý định thật — lời khuyên mang sắc thái lừa dối.","ex":"Lady Macbeth advises, “Look like the innocent flower, but be the serpent under ’t.”","exVi":"Phu nhân Macbeth khuyên: “Hãy như đóa hoa ngây thơ, nhưng ẩn mình như rắn bên dưới.”","src":"William Shakespeare · Macbeth (First Folio, 1623)","level":"general","topics":["Hình ảnh ẩn dụ","Lừa dối"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0038","text":"Parting is such sweet sorrow.","vi":"Lời tạm biệt cũng có thể ngọt ngào vì chứa niềm vui được yêu thương lẫn nỗi buồn chia xa.","ex":"Juliet says, “Parting is such sweet sorrow,” as Romeo leaves.","exVi":"Juliet nói: “Chia tay thật ngọt ngào mà cũng thật buồn,” khi Romeo rời đi.","src":"William Shakespeare · Romeo and Juliet (Second Quarto, 1599)","level":"general","topics":["Tình cảm","Chia xa"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0039","text":"What’s in a name?","vi":"Một cái tên có thực sự quyết định bản chất hay giá trị của một người, một vật không?","ex":"Juliet asks, “What’s in a name?” while thinking about Romeo.","exVi":"Juliet tự hỏi: “Cái tên có ý nghĩa gì?” khi nghĩ về Romeo.","src":"William Shakespeare · Romeo and Juliet (Second Quarto, 1599)","level":"general","topics":["Danh tính","Ngôn ngữ"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0040","text":"Wisely and slow; they stumble that run fast.","vi":"Làm việc khôn ngoan và từ tốn; người vội vàng dễ mắc sai lầm.","ex":"The Friar advises, “Wisely and slow; they stumble that run fast.”","exVi":"Tu sĩ khuyên: “Hãy khôn ngoan và từ tốn; người chạy nhanh dễ vấp ngã.”","src":"William Shakespeare · Romeo and Juliet (Second Quarto, 1599)","level":"general","topics":["Kiên nhẫn","Ra quyết định"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0041","text":"What’s past is prologue.","vi":"Những gì đã qua là phần mở đầu, tạo nền cho những việc sắp tới.","ex":"Gonzalo reflects, “What’s past is prologue,” as events unfold.","exVi":"Gonzalo suy ngẫm: “Quá khứ chỉ là phần mở đầu,” khi sự việc tiếp diễn.","src":"William Shakespeare · The Tempest (First Folio, 1623)","level":"general","topics":["Thời gian","Tương lai"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0042","text":"We are such stuff as dreams are made on.","vi":"Con người và cuộc đời được ví như những giấc mơ mong manh, ngắn ngủi.","ex":"Prospero observes, “We are such stuff as dreams are made on.”","exVi":"Prospero suy ngẫm: “Chúng ta được dệt nên từ chất liệu của những giấc mơ.”","src":"William Shakespeare · The Tempest (First Folio, 1623)","level":"general","topics":["Đời sống","Suy ngẫm"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0043","text":"The rarer action is in virtue than in vengeance.","vi":"Hành động xuất phát từ đức hạnh hiếm và đáng quý hơn việc trả thù.","ex":"Prospero concludes, “The rarer action is in virtue than in vengeance.”","exVi":"Prospero kết luận: “Hành động vì đức hạnh hiếm hơn hành động trả thù.”","src":"William Shakespeare · The Tempest (First Folio, 1623)","level":"general","topics":["Lòng tốt","Tha thứ"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0044","text":"Hell is empty, and all the devils are here.","vi":"Một hình ảnh cường điệu về cảnh hỗn loạn, như thể mọi điều xấu xa đều đang hiện diện.","ex":"Ariel cries, “Hell is empty, and all the devils are here.”","exVi":"Ariel kêu lên: “Địa ngục trống rỗng, và mọi con quỷ đều ở đây.”","src":"William Shakespeare · The Tempest (First Folio, 1623)","level":"general","topics":["Cảm xúc","Hình ảnh ẩn dụ"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0045","text":"The fault, dear Brutus, is not in our stars, but in ourselves.","vi":"Hoàn cảnh hay số phận không phải nguyên nhân duy nhất; lựa chọn của chính ta cũng tạo nên kết quả.","ex":"Cassius argues, “The fault, dear Brutus, is not in our stars, but in ourselves.”","exVi":"Cassius lập luận: “Lỗi không nằm ở các vì sao, mà nằm ở chính chúng ta.”","src":"William Shakespeare · Julius Caesar (First Folio, 1623)","level":"general","topics":["Trách nhiệm","Lựa chọn"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0046","text":"There is a tide in the affairs of men.","vi":"Trong cuộc đời có những thời điểm thuận lợi cần được nhận ra và nắm bắt.","ex":"Brutus says, “There is a tide in the affairs of men.”","exVi":"Brutus nói: “Việc đời cũng có lúc thủy triều lên.”","src":"William Shakespeare · Julius Caesar (First Folio, 1623)","level":"general","topics":["Cơ hội","Thời gian"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0047","text":"Cowards die many times before their deaths.","vi":"Nỗi sợ khiến con người phải chịu đau khổ nhiều lần trước khi biến cố thực sự xảy ra.","ex":"Caesar claims, “Cowards die many times before their deaths.”","exVi":"Caesar cho rằng: “Kẻ hèn nhát chết nhiều lần trước cái chết thật sự.”","src":"William Shakespeare · Julius Caesar (First Folio, 1623)","level":"general","topics":["Dũng khí","Cảm xúc"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0048","text":"Vanity and pride are different things, though the words are often used synonymously.","vi":"Tự hào về bản thân và muốn được người khác ngưỡng mộ là hai điều khác nhau.","ex":"Mary explains, “Vanity and pride are different things, though the words are often used synonymously.”","exVi":"Mary giải thích: “Tự phụ và kiêu hãnh là hai điều khác nhau, dù người ta thường dùng hai từ này như từ đồng nghĩa.”","src":"Jane Austen · Pride and Prejudice (1813)","level":"general","topics":["Tính cách","Tự nhận thức"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0049","text":"I could easily forgive his pride, if he had not mortified mine.","vi":"Tôi có thể tha thứ cho sự kiêu hãnh của anh ấy nếu anh ấy không làm tổn thương lòng tự trọng của tôi.","ex":"Elizabeth replies, “I could easily forgive his pride, if he had not mortified mine.”","exVi":"Elizabeth đáp: “Tôi có thể tha thứ cho sự kiêu hãnh của anh ấy, nếu anh ấy không làm tổn thương lòng tự trọng của tôi.”","src":"Jane Austen · Pride and Prejudice (1813)","level":"general","topics":["Tự trọng","Các mối quan hệ"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0050","text":"Till this moment I never knew myself.","vi":"Mãi đến lúc này tôi mới thật sự hiểu chính mình.","ex":"Elizabeth admits, “Till this moment I never knew myself.”","exVi":"Elizabeth thừa nhận: “Mãi đến lúc này tôi mới hiểu chính mình.”","src":"Jane Austen · Pride and Prejudice (1813)","level":"general","topics":["Tự nhận thức","Thay đổi"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0051","text":"Think only of the past as its remembrance gives you pleasure.","vi":"Hãy chỉ nhớ về quá khứ theo cách đem lại cho bạn niềm vui.","ex":"Elizabeth advises Darcy, “Think only of the past as its remembrance gives you pleasure.”","exVi":"Elizabeth khuyên Darcy: “Chỉ nghĩ về quá khứ khi ký ức ấy đem lại niềm vui cho anh.”","src":"Jane Austen · Pride and Prejudice (1813)","level":"general","topics":["Ký ức","Cảm xúc"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0052","text":"What are men to rocks and mountains?","vi":"Đứng trước cảnh núi non hùng vĩ, con người nhỏ bé biết bao.","ex":"Elizabeth asks, “What are men to rocks and mountains?”","exVi":"Elizabeth hỏi: “Con người thì đáng kể gì trước núi đá?”","src":"Jane Austen · Pride and Prejudice (1813)","level":"general","topics":["Thiên nhiên","Du lịch"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0053","text":"One half of the world cannot understand the pleasures of the other.","vi":"Người có sở thích và hoàn cảnh khác nhau đôi khi khó hiểu niềm vui của nhau.","ex":"Emma says, “One half of the world cannot understand the pleasures of the other.”","exVi":"Emma nói: “Một nửa thế giới không thể hiểu được niềm vui của nửa còn lại.”","src":"Jane Austen · Emma (1815)","level":"general","topics":["Sở thích","Khác biệt"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0054","text":"If I loved you less, I might be able to talk about it more.","vi":"Nếu tình cảm dành cho em ít hơn, có lẽ anh đã dễ nói thành lời hơn.","ex":"Knightley says, “If I loved you less, I might be able to talk about it more.”","exVi":"Knightley nói: “Nếu yêu em ít hơn, có lẽ anh đã có thể nói về tình cảm ấy nhiều hơn.”","src":"Jane Austen · Emma (1815)","level":"general","topics":["Tình yêu","Giao tiếp"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0055","text":"Silly things do cease to be silly if they are done by sensible people in an impudent way.","vi":"Việc ngớ ngẩn đôi khi lại thành ra buồn cười khi người khôn ngoan làm với vẻ táo tợn.","ex":"Silly things do cease to be silly if they are done by sensible people in an impudent way.","exVi":"Việc ngớ ngẩn quả thật không còn ngớ ngẩn nếu được người khôn ngoan làm một cách táo tợn.","src":"Jane Austen · Emma (1815)","level":"general","topics":["Hài hước","Tính cách"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0056","text":"Seldom, very seldom, does complete truth belong to any human disclosure.","vi":"Rất hiếm khi một lời bộc bạch của con người chứa đựng toàn bộ sự thật.","ex":"Emma reflects, “Seldom, very seldom, does complete truth belong to any human disclosure.”","exVi":"Emma suy ngẫm: “Rất hiếm khi một lời bộc bạch của con người chứa đựng toàn bộ sự thật.”","src":"Jane Austen · Emma (1815)","level":"general","topics":["Sự thật","Giao tiếp"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0057","text":"I declare, after all, there is no enjoyment like reading!","vi":"Caroline nói câu này để gây ấn tượng với Darcy; ngữ cảnh khiến lời khen việc đọc mang sắc thái châm biếm.","ex":"Caroline says, “I declare, after all, there is no enjoyment like reading!”","exVi":"Caroline nói: “Tôi xin khẳng định, chẳng có niềm vui nào bằng việc đọc sách!”","src":"Jane Austen · Pride and Prejudice (1813)","level":"general","topics":["Đọc sách","Châm biếm"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0058","text":"Mankind was my business.","vi":"Trách nhiệm lớn nhất của tôi là quan tâm đến con người và phúc lợi chung.","ex":"Marley tells Scrooge, “Mankind was my business.”","exVi":"Marley nói với Scrooge: “Mối quan tâm của tôi là nhân loại.”","src":"Charles Dickens · A Christmas Carol (1843)","level":"general","topics":["Trách nhiệm","Cộng đồng"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0059","text":"I wear the chain I forged in life.","vi":"Tôi đang mang xiềng xích do chính mình tạo nên khi còn sống.","ex":"Marley admits, “I wear the chain I forged in life.”","exVi":"Marley thừa nhận: “Tôi đang mang xiềng xích do chính mình tạo ra khi còn sống.”","src":"Charles Dickens · A Christmas Carol (1843)","level":"general","topics":["Lựa chọn","Trách nhiệm cá nhân"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0060","text":"There is nothing in the world so irresistibly contagious as laughter and good-humour.","vi":"Trên đời, không gì dễ lan tỏa một cách mãnh liệt như tiếng cười và sự vui vẻ.","ex":"Dickens writes, “There is nothing in the world so irresistibly contagious as laughter and good-humour.”","exVi":"Dickens viết: “Trên đời, không gì dễ lan tỏa như tiếng cười và sự vui vẻ.”","src":"Charles Dickens · A Christmas Carol (1843)","level":"general","topics":["Cảm xúc","Giao tiếp"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0061","text":"God bless us, every one!","vi":"Cầu chúc mọi người đều được bình an và may mắn.","ex":"Tiny Tim ends the story with, “God bless us, every one!”","exVi":"Tiny Tim kết thúc câu chuyện bằng lời chúc: “Cầu chúc mọi người đều được bình an!”","src":"Charles Dickens · A Christmas Carol (1843)","level":"general","topics":["Gia đình","Hy vọng"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0062","text":"Please, sir, I want some more.","vi":"Thưa ông, cháu muốn xin thêm một phần nữa ạ.","ex":"Oliver politely asks, “Please, sir, I want some more.”","exVi":"Oliver lễ phép xin: “Thưa ông, cháu muốn xin thêm một phần nữa ạ.”","src":"Charles Dickens · Oliver Twist (1838)","level":"general","topics":["Nhu cầu cơ bản","Công bằng xã hội"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0063","text":"There are books of which the backs and covers are by far the best parts.","vi":"Có những cuốn sách mà phần gáy và bìa lại là phần hay nhất.","ex":"Mr. Brownlow jokes, “there are books of which the backs and covers are by far the best parts.”","exVi":"Ông Brownlow đùa: “Có những cuốn sách mà phần gáy và bìa lại là phần hay nhất.”","src":"Charles Dickens · Oliver Twist (1838)","level":"general","topics":["Đọc sách","Châm biếm"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0064","text":"We need never be ashamed of our tears.","vi":"Ta không cần phải xấu hổ vì những giọt nước mắt của mình.","ex":"Pip reflects, “We need never be ashamed of our tears.”","exVi":"Pip suy ngẫm: “Ta không cần phải xấu hổ vì những giọt nước mắt của mình.”","src":"Charles Dickens · Great Expectations (1861)","level":"general","topics":["Cảm xúc","Chấp nhận bản thân"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0065","text":"Whatever our souls are made of, his and mine are the same.","vi":"Dù tâm hồn chúng tôi được tạo nên từ điều gì, tâm hồn anh ấy và tôi cũng giống nhau.","ex":"Catherine says, “Whatever our souls are made of, his and mine are the same.”","exVi":"Catherine nói: “Dù tâm hồn chúng tôi được tạo nên từ điều gì, tâm hồn anh ấy và tôi cũng giống nhau.”","src":"Emily Brontë · Wuthering Heights (1847)","level":"general","topics":["Tình yêu","Các mối quan hệ"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0066","text":"I am no bird; and no net ensnares me.","vi":"Tôi không phải con chim, và chẳng tấm lưới nào giữ được tôi.","ex":"Jane declares, “I am no bird; and no net ensnares me.”","exVi":"Jane khẳng định: “Tôi không phải con chim, và chẳng tấm lưới nào giữ được tôi.”","src":"Charlotte Brontë · Jane Eyre (1847)","level":"general","topics":["Tự do","Quyền cá nhân"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0067","text":"Beware, for I am fearless and therefore powerful.","vi":"Hãy coi chừng, vì ta không biết sợ nên ta có sức mạnh.","ex":"The creature warns, “Beware, for I am fearless and therefore powerful.”","exVi":"Sinh vật ấy cảnh báo: “Hãy coi chừng, vì ta không biết sợ nên ta có sức mạnh.”","src":"Mary Shelley · Frankenstein (1831)","level":"general","topics":["Dũng khí","Quyền lực"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0068","text":"Who in the world am I? Ah, that’s the great puzzle!","vi":"Mình là ai giữa thế giới này? Đó mới là câu đố lớn.","ex":"Alice asks, “Who in the world am I? Ah, that’s the great puzzle!”","exVi":"Alice tự hỏi: “Mình là ai giữa thế giới này? Đó mới là câu đố lớn.”","src":"Lewis Carroll · Alice’s Adventures in Wonderland (1865)","level":"general","topics":["Bản sắc","Tự nhận thức"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0069","text":"It takes all the running you can do, to keep in the same place.","vi":"Đôi khi phải nỗ lực hết sức chỉ để giữ nguyên vị trí hiện tại.","ex":"The Red Queen observes, “It takes all the running you can do, to keep in the same place.”","exVi":"Nữ hoàng Đỏ nhận xét: “Đôi khi phải chạy hết sức chỉ để giữ nguyên vị trí.”","src":"Lewis Carroll · Through the Looking-Glass (1871)","level":"general","topics":["Nỗ lực","Thay đổi"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0070","text":"I like good strong words, that mean something.","vi":"Tôi thích những từ ngữ mạnh mẽ, rõ nghĩa và có sức nặng.","ex":"Jo says, “I like good strong words, that mean something.”","exVi":"Jo nói: “Tôi thích những từ ngữ mạnh mẽ, rõ nghĩa và có sức nặng.”","src":"Louisa May Alcott · Little Women (1868)","level":"general","topics":["Ngôn ngữ","Giao tiếp"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0071","text":"Make each day both useful and pleasant.","vi":"Hãy làm cho mỗi ngày vừa có ích vừa dễ chịu.","ex":"Mrs. March advises, “Make each day both useful and pleasant.”","exVi":"Bà March khuyên: “Hãy làm cho mỗi ngày vừa có ích vừa dễ chịu.”","src":"Louisa May Alcott · Little Women (1868)","level":"general","topics":["Thói quen","Cân bằng cuộc sống"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0072","text":"In matters of grave importance, style, not sincerity is the vital thing.","vi":"Trong chuyện được cho là hệ trọng, vẻ ngoài đôi khi lại được đặt lên trên sự chân thành.","ex":"Gwendolen remarks, “In matters of grave importance, style, not sincerity is the vital thing.”","exVi":"Gwendolen nhận xét: “Trong chuyện hệ trọng, vẻ ngoài chứ không phải sự chân thành mới là điều thiết yếu.”","src":"Oscar Wilde · The Importance of Being Earnest (1895)","level":"general","topics":["Hình thức","Châm biếm"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0073","text":"A man who knows the price of everything and the value of nothing.","vi":"Một người chỉ biết giá tiền của mọi thứ mà không hiểu giá trị thực của điều gì.","ex":"Lord Darlington calls a cynic, “A man who knows the price of everything and the value of nothing.”","exVi":"Lord Darlington gọi người hoài nghi là: “Kẻ biết giá tiền của mọi thứ nhưng chẳng hiểu giá trị của điều gì.”","src":"Oscar Wilde · Lady Windermere’s Fan (1892)","level":"general","topics":["Tiền bạc","Giá trị sống"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0074","text":"Experience is the name every one gives to their mistakes.","vi":"Người ta thường gọi những sai lầm đã trải qua là kinh nghiệm.","ex":"Dumby quips, “Experience is the name every one gives to their mistakes.”","exVi":"Dumby nói đùa: “Người ta gọi những sai lầm của mình là kinh nghiệm.”","src":"Oscar Wilde · Lady Windermere’s Fan (1892)","level":"general","topics":["Kinh nghiệm","Học từ sai lầm"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0075","text":"We are all in the gutter, but some of us are looking at the stars.","vi":"Ai cũng có lúc ở dưới đáy, nhưng vẫn có người ngước nhìn những điều tốt đẹp phía trước.","ex":"Lord Darlington reflects, “We are all in the gutter, but some of us are looking at the stars.”","exVi":"Lord Darlington suy ngẫm: “Ai cũng có lúc ở dưới đáy, nhưng vẫn có người ngước nhìn những vì sao.”","src":"Oscar Wilde · Lady Windermere’s Fan (1892)","level":"general","topics":["Hy vọng","Nghị lực"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0076","text":"When you have eliminated all which is impossible, then whatever remains however improbable, must be the truth.","vi":"Khi đã loại trừ mọi điều không thể, điều còn lại dù khó tin đến đâu cũng có thể là sự thật.","ex":"When you have eliminated all which is impossible, then whatever remains however improbable, must be the truth.","exVi":"Khi đã loại trừ mọi điều không thể, điều còn lại dù khó tin đến đâu cũng có thể là sự thật.","src":"Arthur Conan Doyle · The Case-Book of Sherlock Holmes (1927)","level":"general","topics":["Suy luận","Sự thật"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0077","text":"There is nothing—absolute nothing—half so much worth doing as simply messing about in boats.","vi":"Không gì thú vị bằng được thư thả vui đùa quanh những con thuyền.","ex":"There is nothing—absolute nothing—half so much worth doing as simply messing about in boats.","exVi":"Không gì thú vị bằng được thư thả vui đùa quanh những con thuyền.","src":"Kenneth Grahame · The Wind in the Willows (1908)","level":"general","topics":["Sở thích","Thư giãn"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0078","text":"A foolish consistency is the hobgoblin of little minds.","vi":"Bám vào sự nhất quán một cách máy móc là biểu hiện của tư duy nhỏ hẹp.","ex":"Emerson writes, “A foolish consistency is the hobgoblin of little minds.”","exVi":"Emerson viết: “Sự nhất quán máy móc là nỗi ám ảnh của những tâm trí nhỏ hẹp.”","src":"Ralph Waldo Emerson · Self-Reliance, Essays: First Series (1841)","level":"general","topics":["Tư duy","Tự chủ"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0079","text":"Trust thyself: every heart vibrates to that iron string.","vi":"Hãy tin vào chính mình; mỗi trái tim đều rung lên trước tiếng gọi ấy.","ex":"My mentor often says, “Trust thyself: every heart vibrates to that iron string.”","exVi":"Người hướng dẫn của tôi thường nói: “Hãy tin vào chính mình; mỗi trái tim đều rung lên trước tiếng gọi ấy.”","src":"Ralph Waldo Emerson · Self-Reliance, Essays: First Series (1841)","level":"general","topics":["Tự tin","Phát triển bản thân"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0080","text":"Imitation is suicide.","vi":"Bắt chước người khác đến mức đánh mất bản thân cũng giống như tự hủy hoại mình.","ex":"Emerson’s concise warning is, “Imitation is suicide.”","exVi":"Lời cảnh tỉnh ngắn gọn của Emerson là: “Bắt chước là tự hủy hoại mình.”","src":"Ralph Waldo Emerson · Self-Reliance, Essays: First Series (1841)","level":"general","topics":["Bản sắc","Tự chủ"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0081","text":"Simplify, simplify.","vi":"Hãy đơn giản hóa cuộc sống, bỏ bớt những điều không cần thiết.","ex":"Thoreau’s advice for a less cluttered life is simple: “Simplify, simplify.”","exVi":"Lời khuyên của Thoreau để sống bớt rườm rà thật đơn giản: “Hãy đơn giản hóa.”","src":"Henry David Thoreau · Walden (1854)","level":"general","topics":["Lối sống","Cân bằng cuộc sống"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0082","text":"If a plant cannot live according to its nature, it dies; and so a man.","vi":"Nếu không được sống đúng với bản tính của mình, cây sẽ chết; con người cũng vậy.","ex":"Thoreau writes, “If a plant cannot live according to its nature, it dies; and so a man.”","exVi":"Thoreau viết: “Nếu cây không thể sống đúng với bản tính của nó, nó sẽ chết; con người cũng vậy.”","src":"Henry David Thoreau · Resistance to Civil Government (1849)","level":"general","topics":["Tự do","Thiên nhiên"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0083","text":"I was not born to be forced. I will breathe after my own fashion.","vi":"Tôi không sinh ra để bị ép buộc; tôi sẽ sống theo cách của riêng mình.","ex":"Thoreau declares, “I was not born to be forced. I will breathe after my own fashion.”","exVi":"Thoreau tuyên bố: “Tôi không sinh ra để bị ép buộc. Tôi sẽ sống theo cách của riêng mình.”","src":"Henry David Thoreau · Resistance to Civil Government (1849)","level":"general","topics":["Tự do","Lựa chọn"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0084","text":"To travel hopefully is a better thing than to arrive.","vi":"Hành trình với niềm hy vọng đôi khi đáng quý hơn cả lúc chạm đến đích.","ex":"Stevenson suggests, “To travel hopefully is a better thing than to arrive.”","exVi":"Stevenson gợi ý: “Lên đường với niềm hy vọng đôi khi còn quý hơn cả lúc tới đích.”","src":"Robert Louis Stevenson · El Dorado, Virginibus Puerisque (1881)","level":"general","topics":["Du lịch","Kiên trì"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0085","text":"For my part, I travel not to go anywhere, but to go.","vi":"Riêng tôi, đi du lịch không phải để đến một nơi nào đó, mà để được lên đường.","ex":"Stevenson writes, “For my part, I travel not to go anywhere, but to go.”","exVi":"Stevenson viết: “Riêng tôi, đi không phải để đến nơi nào đó, mà để được lên đường.”","src":"Robert Louis Stevenson · An Inland Voyage (1878)","level":"general","topics":["Du lịch","Trải nghiệm"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0086","text":"The rule is, jam to-morrow and jam yesterday—but never jam to-day.","vi":"Luật là ngày mai có mứt, hôm qua cũng có mứt, nhưng hôm nay thì không bao giờ.","ex":"The Red Queen explains, “The rule is, jam to-morrow and jam yesterday—but never jam to-day.”","exVi":"Nữ hoàng Đỏ giải thích: “Luật là ngày mai có mứt, hôm qua cũng có, nhưng hôm nay thì không.”","src":"Lewis Carroll · Through the Looking-Glass (1871)","level":"general","topics":["Thời gian","Nghịch lý"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0087","text":"There is a grandeur in this view of life.","vi":"Cách nhìn này về sự sống thật hùng vĩ.","ex":"Darwin concludes, “There is a grandeur in this view of life.”","exVi":"Darwin kết luận: “Cách nhìn này về sự sống thật hùng vĩ.”","src":"Charles Darwin · On the Origin of Species (1859)","level":"general","topics":["Thiên nhiên","Khoa học"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0088","text":"I went to the woods because I wished to live deliberately.","vi":"Tôi vào rừng vì muốn sống một cách có chủ đích.","ex":"Thoreau begins, “I went to the woods because I wished to live deliberately.”","exVi":"Thoreau mở đầu: “Tôi vào rừng vì muốn sống một cách có chủ đích.”","src":"Henry David Thoreau · Walden (1854)","level":"general","topics":["Lối sống","Tự nhận thức"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0089","text":"Rather than love, than money, than fame, give me truth.","vi":"Thay vì tình yêu, tiền bạc hay danh vọng, hãy cho tôi sự thật.","ex":"Thoreau’s closing appeal is, “Rather than love, than money, than fame, give me truth.”","exVi":"Lời kết của Thoreau là: “Thay vì tình yêu, tiền bạc hay danh vọng, hãy cho tôi sự thật.”","src":"Henry David Thoreau · Walden (1854)","level":"general","topics":["Sự thật","Giá trị sống"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0090","text":"As if you could kill time without injuring eternity.","vi":"Cứ như thể ta có thể giết thời gian mà không làm tổn hại đến sự vĩnh hằng.","ex":"Thoreau challenges idleness: “As if you could kill time without injuring eternity.”","exVi":"Thoreau chất vấn thói sống nhàn tản: “Cứ như thể ta có thể giết thời gian mà không làm tổn hại đến sự vĩnh hằng.”","src":"Henry David Thoreau · Walden (1854)","level":"general","topics":["Thời gian","Mục đích sống"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0091","text":"The mass of men lead lives of quiet desperation.","vi":"Phần đông mọi người sống trong nỗi tuyệt vọng âm thầm.","ex":"Thoreau observes, “The mass of men lead lives of quiet desperation.”","exVi":"Thoreau nhận xét: “Phần đông mọi người sống trong nỗi tuyệt vọng âm thầm.”","src":"Henry David Thoreau · Walden (1854)","level":"general","topics":["Đời sống","Cảm xúc"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0092","text":"If you have built castles in the air, your work need not be lost.","vi":"Nếu bạn đã dựng những lâu đài trên không, công sức ấy vẫn chưa hẳn vô ích.","ex":"Thoreau reassures dreamers, “If you have built castles in the air, your work need not be lost.”","exVi":"Thoreau động viên những người mơ ước: “Nếu bạn đã dựng lâu đài trên không, công sức ấy vẫn chưa hẳn vô ích.”","src":"Henry David Thoreau · Walden (1854)","level":"general","topics":["Ước mơ","Kiên trì"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0093","text":"I can resist everything except temptation.","vi":"Tôi có thể cưỡng lại mọi thứ, trừ cám dỗ.","ex":"Lord Darlington jokes, “I can resist everything except temptation.”","exVi":"Lord Darlington nói đùa: “Tôi cưỡng lại được mọi thứ, ngoại trừ cám dỗ.”","src":"Oscar Wilde · Lady Windermere’s Fan (1892)","level":"general","topics":["Cám dỗ","Hài hước"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0094","text":"The truth is rarely pure and never simple.","vi":"Sự thật hiếm khi thuần khiết và chẳng bao giờ đơn giản.","ex":"Algernon remarks, “The truth is rarely pure and never simple.”","exVi":"Algernon nhận xét: “Sự thật hiếm khi thuần khiết và chẳng bao giờ đơn giản.”","src":"Oscar Wilde · The Importance of Being Earnest (1895)","level":"general","topics":["Sự thật","Giao tiếp"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0095","text":"The only way to get rid of a temptation is to yield to it.","vi":"Cách duy nhất để thoát khỏi một cám dỗ là nhượng bộ nó.","ex":"Lord Henry advises, “The only way to get rid of a temptation is to yield to it.”","exVi":"Lord Henry khuyên: “Cách duy nhất để thoát khỏi một cám dỗ là nhượng bộ nó.”","src":"Oscar Wilde · The Picture of Dorian Gray (1891)","level":"general","topics":["Cám dỗ","Lựa chọn"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0096","text":"Life is much too important a thing ever to talk seriously about it.","vi":"Cuộc đời quan trọng đến mức chẳng nên bàn về nó một cách quá nghiêm túc.","ex":"Prince Paul quips, “Life is much too important a thing ever to talk seriously about it.”","exVi":"Hoàng tử Paul nói đùa: “Cuộc đời quan trọng đến mức chẳng nên bàn về nó một cách quá nghiêm túc.”","src":"Oscar Wilde · Vera; or, the Nihilists (1883)","level":"general","topics":["Đời sống","Hài hước"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0097","text":"Every thing’s got a moral, if only you can find it.","vi":"Mọi chuyện đều có một bài học, miễn là ta biết tìm ra.","ex":"The Duchess insists, “Every thing’s got a moral, if only you can find it.”","exVi":"Nữ Công tước quả quyết: “Mọi chuyện đều có bài học, miễn là ta biết tìm ra.”","src":"Lewis Carroll · Alice’s Adventures in Wonderland (1865)","level":"general","topics":["Bài học","Suy ngẫm"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0098","text":"Heard melodies are sweet, but those unheard are sweeter.","vi":"Giai điệu được nghe đã ngọt ngào, nhưng những giai điệu chưa vang lên còn đẹp hơn.","ex":"Keats writes, “Heard melodies are sweet, but those unheard are sweeter.”","exVi":"Keats viết: “Giai điệu được nghe đã ngọt ngào, nhưng những giai điệu chưa vang lên còn đẹp hơn.”","src":"John Keats · Ode on a Grecian Urn (1820)","level":"general","topics":["Nghệ thuật","Âm nhạc"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0099","text":"If Winter comes, can Spring be far behind?","vi":"Nếu mùa đông đã đến, mùa xuân liệu còn xa không?","ex":"Shelley ends with a hopeful question: “If Winter comes, can Spring be far behind?”","exVi":"Shelley khép lại bằng câu hỏi đầy hy vọng: “Nếu mùa đông đến, mùa xuân liệu còn xa?”","src":"Percy Bysshe Shelley · Ode to the West Wind (1820)","level":"general","topics":["Hy vọng","Thời tiết"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0100","text":"The Child is father of the Man.","vi":"Đứa trẻ là nền móng hình thành nên người trưởng thành.","ex":"Wordsworth reflects, “The Child is father of the Man.”","exVi":"Wordsworth suy ngẫm: “Đứa trẻ là cha của người đàn ông.”","src":"William Wordsworth · My Heart Leaps Up (1807)","level":"general","topics":["Tuổi thơ","Phát triển bản thân"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0101","text":"Better to reign in Hell than serve in Heaven.","vi":"Thà làm chủ nơi địa ngục còn hơn phục tùng trên thiên đường.","ex":"Milton’s character declares, “Better to reign in Hell than serve in Heaven.”","exVi":"Nhân vật của Milton tuyên bố: “Thà làm chủ nơi địa ngục còn hơn phục tùng trên thiên đường.”","src":"John Milton · Paradise Lost (1667)","level":"general","topics":["Quyền lực","Tự do"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0102","text":"Ah, but a man’s reach should exceed his grasp, or what’s a heaven for?","vi":"Khát vọng của con người nên vượt quá điều họ đang nắm giữ; nếu không, thiên đường có ý nghĩa gì?","ex":"Browning asks, “Ah, but a man’s reach should exceed his grasp, or what’s a heaven for?”","exVi":"Browning đặt câu hỏi: “Khát vọng của con người nên vượt điều họ nắm giữ; nếu không, thiên đường có ý nghĩa gì?”","src":"Robert Browning · Andrea del Sarto (1855)","level":"general","topics":["Tham vọng","Phát triển bản thân"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0103","text":"Art is long, and Time is fleeting.","vi":"Nghệ thuật cần thời gian dài, còn thời gian đời người thì trôi rất nhanh.","ex":"Longfellow reminds readers, “Art is long, and Time is fleeting.”","exVi":"Longfellow nhắc người đọc: “Nghệ thuật cần thời gian dài, còn thời gian thì trôi nhanh.”","src":"Henry Wadsworth Longfellow · A Psalm of Life (1838)","level":"general","topics":["Thời gian","Nghệ thuật"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0104","text":"These are the sights, Harriet, to do one good.","vi":"Những cảnh tượng này khiến người ta sống tốt hơn, Harriet ạ.","ex":"Emma says, “These are the sights, Harriet, to do one good.”","exVi":"Emma nói: “Những cảnh tượng này khiến người ta sống tốt hơn, Harriet ạ.”","src":"Jane Austen · Emma (1815)","level":"general","topics":["Lòng tốt","Tính cách"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0105","text":"It is very often nothing but our own vanity that deceives us.","vi":"Rất thường khi chính lòng tự phụ khiến chúng ta nhìn nhận sai lầm.","ex":"Elizabeth warns Jane, “It is very often nothing but our own vanity that deceives us.”","exVi":"Elizabeth nhắc Jane: “Rất thường khi chính lòng tự phụ khiến chúng ta nhìn nhận sai lầm.”","src":"Jane Austen · Pride and Prejudice (1813)","level":"general","topics":["Tự nhận thức","Quan hệ"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0106","text":"A person may be proud without being vain.","vi":"Một người có thể tự hào mà không hề tự phụ.","ex":"Mary distinguishes two traits: “A person may be proud without being vain.”","exVi":"Mary phân biệt hai nét tính cách: “Một người có thể tự hào mà không tự phụ.”","src":"Jane Austen · Pride and Prejudice (1813)","level":"general","topics":["Tính cách","Tự nhận thức"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0107","text":"There will be enough for every hope and every fear.","vi":"Sẽ có đủ chỗ cho mọi niềm hy vọng và nỗi lo âu.","ex":"Emma imagines, “There will be enough for every hope and every fear.”","exVi":"Emma hình dung: “Sẽ có đủ chỗ cho mọi niềm hy vọng và nỗi lo âu.”","src":"Jane Austen · Emma (1815)","level":"general","topics":["Tự trọng","Quan hệ"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0108","text":"It is a far, far better thing that I do than I have ever done.","vi":"Việc tôi đang làm tốt đẹp hơn mọi điều tôi từng làm.","ex":"Carton says, “It is a far, far better thing that I do than I have ever done.”","exVi":"Carton nói: “Việc tôi đang làm tốt đẹp hơn mọi điều tôi từng làm.”","src":"Charles Dickens · A Tale of Two Cities (1859)","level":"general","topics":["Thời đại","Đối lập"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0109","text":"We had everything before us, we had nothing before us.","vi":"Chúng ta có mọi thứ ở phía trước, nhưng cũng chẳng có gì ở phía trước.","ex":"The narrator describes the era: “We had everything before us, we had nothing before us.”","exVi":"Người kể mô tả thời đại: “Chúng ta có mọi thứ ở phía trước, nhưng cũng chẳng có gì.”","src":"Charles Dickens · A Tale of Two Cities (1859)","level":"general","topics":["Tương lai","Đối lập"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0110","text":"Men at some time are masters of their fates.","vi":"Có lúc, con người có thể tự quyết định số phận mình.","ex":"Cassius argues, “Men at some time are masters of their fates.”","exVi":"Cassius lập luận: “Có lúc, con người có thể tự quyết định số phận mình.”","src":"William Shakespeare · Julius Caesar (c. 1599)","level":"general","topics":["Trách nhiệm","Lựa chọn"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0111","text":"This above all: to thine own self be true.","vi":"Trên hết, hãy sống chân thật với chính mình.","ex":"Polonius advises Laertes, “This above all: to thine own self be true.”","exVi":"Polonius khuyên Laertes: “Trên hết, hãy sống chân thật với chính mình.”","src":"William Shakespeare · Hamlet (c. 1600)","level":"general","topics":["Bản sắc","Sự trung thực"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0112","text":"Some are born great, some achieve greatness, and some have greatness thrust upon them.","vi":"Có người sinh ra đã vĩ đại, có người tự đạt được điều đó, và có người được trao cho danh tiếng.","ex":"The play says, “Some are born great, some achieve greatness, and some have greatness thrust upon them.”","exVi":"Vở kịch viết: “Có người sinh ra đã vĩ đại, có người tự đạt được điều đó, có người được trao danh tiếng.”","src":"William Shakespeare · Twelfth Night (c. 1601)","level":"general","topics":["Thành công","Cơ hội"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0113","text":"There's no art to find the mind's construction in the face.","vi":"Không thể nhìn mặt mà đoán chính xác tâm trí con người.","ex":"Duncan reflects, “There's no art to find the mind's construction in the face.”","exVi":"Duncan suy ngẫm: “Không thể nhìn mặt mà đoán chính xác tâm trí con người.”","src":"William Shakespeare · Macbeth (c. 1606)","level":"general","topics":["Chấp nhận","Quá khứ"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0114","text":"Nothing is so painful to the human mind as a great and sudden change.","vi":"Không gì khiến tâm trí con người đau đớn bằng một thay đổi lớn và bất ngờ.","ex":"Victor reflects, “Nothing is so painful to the human mind as a great and sudden change.”","exVi":"Victor suy ngẫm: “Không gì khiến tâm trí con người đau đớn bằng một thay đổi lớn và bất ngờ.”","src":"Mary Shelley · Frankenstein; or, The Modern Prometheus (1818)","level":"general","topics":["Thay đổi","Cảm xúc"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0115","text":"I ought to be thy Adam; but I am rather the fallen angel.","vi":"Lẽ ra ta phải là Adam của ngươi, nhưng ta lại giống thiên thần sa ngã hơn.","ex":"The creature protests, “I ought to be thy Adam; but I am rather the fallen angel.”","exVi":"Sinh vật ấy phản kháng: “Lẽ ra ta phải là Adam của ngươi, nhưng ta lại giống thiên thần sa ngã hơn.”","src":"Mary Shelley · Frankenstein; or, The Modern Prometheus (1818)","level":"general","topics":["Cô đơn","Quan hệ"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0116","text":"I was benevolent and good; misery made me a fiend.","vi":"Ta từng nhân hậu và tốt bụng; khổ đau đã biến ta thành quỷ dữ.","ex":"The creature says, “I was benevolent and good; misery made me a fiend.”","exVi":"Sinh vật ấy nói: “Ta từng nhân hậu và tốt bụng; khổ đau đã biến ta thành quỷ dữ.”","src":"Mary Shelley · Frankenstein; or, The Modern Prometheus (1818)","level":"general","topics":["Cảm xúc","Môi trường sống"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0117","text":"Make me happy, and I shall again be virtuous.","vi":"Hãy khiến ta hạnh phúc, rồi ta sẽ lại sống lương thiện.","ex":"The creature pleads, “Make me happy, and I shall again be virtuous.”","exVi":"Sinh vật ấy cầu xin: “Hãy khiến ta hạnh phúc, rồi ta sẽ lại sống lương thiện.”","src":"Mary Shelley · Frankenstein; or, The Modern Prometheus (1818)","level":"general","topics":["Hạnh phúc","Lòng tốt"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0118","text":"It is not down on any map; true places never are.","vi":"Những nơi chốn có thật thì không bao giờ được ghi trên bản đồ.","ex":"Ishmael muses, “It is not down on any map; true places never are.”","exVi":"Ishmael suy ngẫm: “Những nơi chốn có thật thì không bao giờ được ghi trên bản đồ.”","src":"Herman Melville · Moby-Dick; or, The Whale (1851)","level":"general","topics":["Du lịch","Nơi chốn"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0119","text":"I have no data yet.","vi":"Tôi vẫn chưa có dữ liệu nào.","ex":"Holmes replies, “I have no data yet.”","exVi":"Holmes đáp: “Tôi vẫn chưa có dữ liệu nào.”","src":"Arthur Conan Doyle · A Scandal in Bohemia (1891)","level":"general","topics":["Khoa học","Tư duy"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0120","text":"It is a capital mistake to theorize before one has data.","vi":"Đưa ra giả thuyết trước khi có dữ liệu là một sai lầm nghiêm trọng.","ex":"Holmes cautions Watson, “It is a capital mistake to theorize before one has data.”","exVi":"Holmes cảnh báo Watson: “Đưa ra giả thuyết trước khi có dữ liệu là một sai lầm nghiêm trọng.”","src":"Arthur Conan Doyle · A Scandal in Bohemia (1891)","level":"general","topics":["Khoa học","Tư duy phản biện"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0121","text":"The world is full of obvious things which nobody by any chance ever observes.","vi":"Thế giới có vô số điều hiển nhiên mà chẳng mấy ai để ý quan sát.","ex":"Holmes remarks, “The world is full of obvious things which nobody by any chance ever observes.”","exVi":"Holmes nhận xét: “Thế giới có vô số điều hiển nhiên mà chẳng mấy ai để ý quan sát.”","src":"Arthur Conan Doyle · The Hound of the Baskervilles (1902)","level":"general","topics":["Quan sát","Tư duy"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0122","text":"You see, but you do not observe.","vi":"Anh nhìn thấy, nhưng anh không thật sự quan sát.","ex":"Holmes tells Watson, “You see, but you do not observe.”","exVi":"Holmes nói với Watson: “Anh nhìn thấy, nhưng anh không thật sự quan sát.”","src":"Arthur Conan Doyle · A Scandal in Bohemia (1891)","level":"general","topics":["Quan sát","Học tập"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0123","text":"I will honour Christmas in my heart, and try to keep it all the year.","vi":"Tôi sẽ trân trọng Giáng sinh trong tim và cố gắng giữ tinh thần ấy suốt cả năm.","ex":"Scrooge promises, “I will honour Christmas in my heart, and try to keep it all the year.”","exVi":"Scrooge hứa: “Tôi sẽ trân trọng Giáng sinh trong tim và cố gắng giữ tinh thần ấy suốt cả năm.”","src":"Charles Dickens · A Christmas Carol (1843)","level":"general","topics":["Lòng tốt","Lễ hội"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0124","text":"I believe that it has done me good, and will do me good.","vi":"Tôi tin rằng điều ấy đã giúp ích cho mình và sẽ còn tiếp tục như vậy.","ex":"Fred reflects, “I believe that it has done me good, and will do me good.”","exVi":"Fred suy ngẫm: “Tôi tin rằng điều ấy đã giúp ích cho mình và sẽ còn tiếp tục như vậy.”","src":"Charles Dickens · A Christmas Carol (1843)","level":"general","topics":["Lễ hội","Lòng biết ơn"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0125","text":"I am content to suffer alone, while my sufferings shall endure.","vi":"Ta chấp nhận chịu đựng một mình, chừng nào nỗi đau còn kéo dài.","ex":"The creature says, “I am content to suffer alone, while my sufferings shall endure.”","exVi":"Sinh vật ấy nói: “Ta chấp nhận chịu đựng một mình, chừng nào nỗi đau còn kéo dài.”","src":"Mary Shelley · Frankenstein; or, The Modern Prometheus (1818)","level":"general","topics":["Cô đơn","Sức chịu đựng"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0126","text":"You are my creator, but I am your master; obey!","vi":"Ngươi là người tạo ra ta, nhưng ta mới là chủ nhân của ngươi; hãy nghe lệnh!","ex":"The creature warns Victor, “You are my creator, but I am your master; obey!”","exVi":"Sinh vật ấy cảnh báo Victor: “Ngươi là người tạo ra ta, nhưng ta mới là chủ nhân; hãy nghe lệnh!”","src":"Mary Shelley · Frankenstein; or, The Modern Prometheus (1818)","level":"general","topics":["Quyền lực","Quan hệ"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0127","text":"The desert mountains and dreary glaciers are my refuge.","vi":"Những ngọn núi hoang vu và sông băng lạnh lẽo là nơi trú ẩn của ta.","ex":"The creature explains, “The desert mountains and dreary glaciers are my refuge.”","exVi":"Sinh vật ấy giải thích: “Những ngọn núi hoang vu và sông băng lạnh lẽo là nơi trú ẩn của ta.”","src":"Mary Shelley · Frankenstein; or, The Modern Prometheus (1818)","level":"general","topics":["Thiên nhiên","Nơi chốn"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0128","text":"If there is no struggle, there is no progress.","vi":"Không có đấu tranh thì sẽ không có tiến bộ.","ex":"Douglass insists, “If there is no struggle, there is no progress.”","exVi":"Douglass khẳng định: “Không có đấu tranh thì sẽ không có tiến bộ.”","src":"Frederick Douglass · West India Emancipation (speech, 1857)","level":"general","topics":["Nỗ lực","Tiến bộ"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0129","text":"Power concedes nothing without a demand.","vi":"Quyền lực chẳng tự nhường điều gì nếu không có yêu cầu.","ex":"Douglass argues, “Power concedes nothing without a demand.”","exVi":"Douglass lập luận: “Quyền lực chẳng tự nhường điều gì nếu không có yêu cầu.”","src":"Frederick Douglass · West India Emancipation (speech, 1857)","level":"general","topics":["Quyền lực","Công bằng"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0130","text":"The world will little note, nor long remember what we say here.","vi":"Thế giới sẽ ít để ý, cũng chẳng nhớ lâu những gì chúng ta nói ở đây.","ex":"Lincoln reflects, “The world will little note, nor long remember what we say here.”","exVi":"Lincoln suy ngẫm: “Thế giới sẽ ít để ý, cũng chẳng nhớ lâu những gì chúng ta nói ở đây.”","src":"Abraham Lincoln · Gettysburg Address (1863)","level":"general","topics":["Lịch sử","Khiêm nhường"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0131","text":"Government of the people, by the people, and for the people, shall not perish from the earth.","vi":"Chính quyền của dân, do dân và vì dân sẽ không biến mất khỏi thế gian.","ex":"Government of the people, by the people, and for the people, shall not perish from the earth.","exVi":"Chính quyền của dân, do dân và vì dân sẽ không biến mất khỏi thế gian.","src":"Abraham Lincoln · Gettysburg Address (1863)","level":"general","topics":["Cộng đồng","Công bằng"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0132","text":"I want to do something splendid before I go into my castle.","vi":"Tôi muốn làm điều gì đó thật đáng tự hào trước khi bước vào lâu đài của mình.","ex":"Jo dreams, “I want to do something splendid before I go into my castle.”","exVi":"Jo mơ ước: “Tôi muốn làm điều gì đó thật đáng tự hào trước khi bước vào lâu đài của mình.”","src":"Louisa May Alcott · Little Women (1868)","level":"general","topics":["Ước mơ","Thành tựu"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0133","text":"I only wish we may all keep well and be together; nothing else.","vi":"Tôi chỉ mong tất cả chúng ta luôn khỏe mạnh và được ở bên nhau; không gì hơn.","ex":"Beth says, “I only wish we may all keep well and be together; nothing else.”","exVi":"Beth nói: “Tôi chỉ mong tất cả chúng ta luôn khỏe mạnh và được ở bên nhau; không gì hơn.”","src":"Louisa May Alcott · Little Women (1868)","level":"general","topics":["Gia đình","Sức khỏe"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0134","text":"Better sleep with a sober cannibal than a drunken Christian.","vi":"Ngủ cùng một người ăn thịt người tỉnh táo còn hơn với một người Cơ Đốc say xỉn.","ex":"Ishmael jokes, “Better sleep with a sober cannibal than a drunken Christian.”","exVi":"Ishmael nói đùa: “Ngủ cùng người ăn thịt người tỉnh táo còn hơn với người Cơ Đốc say xỉn.”","src":"Herman Melville · Moby-Dick; or, The Whale (1851)","level":"general","topics":["Hài hước","Định kiến"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0135","text":"The very essence of romance is uncertainty.","vi":"Điều cốt lõi của sự lãng mạn chính là tính bất định.","ex":"Algernon says, “The very essence of romance is uncertainty.”","exVi":"Algernon nói: “Điều cốt lõi của sự lãng mạn chính là tính bất định.”","src":"Oscar Wilde · The Importance of Being Earnest (1895)","level":"general","topics":["Tình yêu","Bất định"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0136","text":"It is very romantic to be in love.","vi":"Đang yêu là một điều thật lãng mạn.","ex":"Algernon remarks, “It is very romantic to be in love.”","exVi":"Algernon nhận xét: “Đang yêu là một điều thật lãng mạn.”","src":"Oscar Wilde · The Importance of Being Earnest (1895)","level":"general","topics":["Tình yêu","Cảm xúc"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0137","text":"Nothing annoys people so much as not receiving invitations.","vi":"Không gì khiến người ta khó chịu bằng việc không được mời.","ex":"Algernon jokes, “Nothing annoys people so much as not receiving invitations.”","exVi":"Algernon đùa: “Không gì khiến người ta khó chịu bằng việc không được mời.”","src":"Oscar Wilde · The Importance of Being Earnest (1895)","level":"general","topics":["Giao tiếp","Hài hước"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0138","text":"A man who marries without knowing Bunbury has a very tedious time of it.","vi":"Người đàn ông kết hôn mà không biết Bunbury sẽ có một cuộc sống rất tẻ nhạt.","ex":"Algernon quips, “A man who marries without knowing Bunbury has a very tedious time of it.”","exVi":"Algernon nói đùa: “Người đàn ông kết hôn mà không biết Bunbury sẽ có cuộc sống rất tẻ nhạt.”","src":"Oscar Wilde · The Importance of Being Earnest (1895)","level":"general","topics":["Hôn nhân","Hài hước"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0139","text":"In married life three is company and two is none.","vi":"Trong đời sống hôn nhân, ba người mới vui, còn hai người thì chẳng vui chút nào.","ex":"Algernon jokes, “In married life three is company and two is none.”","exVi":"Algernon đùa: “Trong đời sống hôn nhân, ba người mới vui, còn hai người thì chẳng vui chút nào.”","src":"Oscar Wilde · The Importance of Being Earnest (1895)","level":"general","topics":["Hôn nhân","Hài hước"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0140","text":"I love scrapes. They are the only things that are never serious.","vi":"Tôi thích những phen rắc rối. Chúng là thứ duy nhất chẳng bao giờ nghiêm trọng.","ex":"Algernon laughs, “I love scrapes. They are the only things that are never serious.”","exVi":"Algernon bật cười: “Tôi thích những phen rắc rối. Chúng là thứ duy nhất chẳng bao giờ nghiêm trọng.”","src":"Oscar Wilde · The Importance of Being Earnest (1895)","level":"general","topics":["Rắc rối","Hài hước"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0141","text":"The good ended happily, and the bad unhappily. That is what Fiction means.","vi":"Người tốt có kết thúc hạnh phúc, kẻ xấu thì không. Đó là ý nghĩa của truyện hư cấu.","ex":"Miss Prism declares, “The good ended happily, and the bad unhappily. That is what Fiction means.”","exVi":"Cô Prism khẳng định: “Người tốt có kết thúc hạnh phúc, kẻ xấu thì không. Đó là ý nghĩa của truyện hư cấu.”","src":"Oscar Wilde · The Importance of Being Earnest (1895)","level":"general","topics":["Văn học","Công bằng"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0142","text":"Memory, my dear Cecily, is the diary that we all carry about with us.","vi":"Cecily thân mến, ký ức là cuốn nhật ký mà ai trong chúng ta cũng mang theo.","ex":"Miss Prism tells Cecily, “Memory, my dear Cecily, is the diary that we all carry about with us.”","exVi":"Cô Prism nói với Cecily: “Ký ức là cuốn nhật ký mà ai trong chúng ta cũng mang theo.”","src":"Oscar Wilde · The Importance of Being Earnest (1895)","level":"general","topics":["Ký ức","Thời gian"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0143","text":"One must be serious about something, if one wants to have any amusement in life.","vi":"Muốn cuộc sống có niềm vui thì ta cũng phải nghiêm túc với điều gì đó.","ex":"Algernon observes, “One must be serious about something, if one wants to have any amusement in life.”","exVi":"Algernon nhận xét: “Muốn cuộc sống có niềm vui thì ta cũng phải nghiêm túc với điều gì đó.”","src":"Oscar Wilde · The Importance of Being Earnest (1895)","level":"general","topics":["Cuộc sống","Sự cân bằng"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0144","text":"One should always eat muffins quite calmly. It is the only way to eat them.","vi":"Ta nên ăn bánh muffin thật bình thản. Đó là cách duy nhất để ăn chúng.","ex":"Algernon insists, “One should always eat muffins quite calmly. It is the only way to eat them.”","exVi":"Algernon quả quyết: “Ta nên ăn bánh muffin thật bình thản. Đó là cách duy nhất để ăn chúng.”","src":"Oscar Wilde · The Importance of Being Earnest (1895)","level":"general","topics":["Đồ ăn","Hài hước"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0145","text":"When I am in trouble, eating is the only thing that consoles me.","vi":"Khi gặp chuyện rắc rối, ăn uống là điều duy nhất an ủi tôi.","ex":"Algernon admits, “When I am in trouble, eating is the only thing that consoles me.”","exVi":"Algernon thừa nhận: “Khi gặp chuyện rắc rối, ăn uống là điều duy nhất an ủi tôi.”","src":"Oscar Wilde · The Importance of Being Earnest (1895)","level":"general","topics":["Đồ ăn","An ủi"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0146","text":"Whenever one has anything unpleasant to say, one should always be quite candid.","vi":"Khi phải nói điều gì không dễ nghe, ta nên thẳng thắn.","ex":"Cecily advises, “Whenever one has anything unpleasant to say, one should always be quite candid.”","exVi":"Cecily khuyên: “Khi phải nói điều gì không dễ nghe, ta nên thẳng thắn.”","src":"Oscar Wilde · The Importance of Being Earnest (1895)","level":"general","topics":["Giao tiếp","Sự thành thật"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0147","text":"I never approve, or disapprove, of anything now.","vi":"Giờ đây tôi chẳng tán thành hay phản đối bất cứ điều gì.","ex":"Lord Henry says, “I never approve, or disapprove, of anything now.”","exVi":"Lord Henry nói: “Giờ đây tôi chẳng tán thành hay phản đối bất cứ điều gì.”","src":"Oscar Wilde · The Picture of Dorian Gray (1890)","level":"general","topics":["Danh tiếng","Xã hội"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0148","text":"Experience was of no ethical value. It was merely the name men gave to their mistakes.","vi":"Trải nghiệm không mang giá trị đạo đức; đó chỉ là tên gọi người ta dành cho sai lầm của mình.","ex":"Experience was of no ethical value. It was merely the name men gave to their mistakes.","exVi":"Người kể chuyện suy ngẫm: “Trải nghiệm không mang giá trị đạo đức; đó chỉ là tên gọi dành cho sai lầm.”","src":"Oscar Wilde · The Picture of Dorian Gray (1890)","level":"general","topics":["Trải nghiệm","Sai lầm"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0149","text":"The secret of remaining young is never to have an emotion that is unbecoming.","vi":"Bí quyết giữ được vẻ trẻ trung là đừng để mình có cảm xúc làm mất phong thái.","ex":"Lord Henry advises, “The secret of remaining young is never to have an emotion that is unbecoming.”","exVi":"Lord Henry khuyên: “Bí quyết giữ vẻ trẻ trung là đừng để mình có cảm xúc làm mất phong thái.”","src":"Oscar Wilde · The Picture of Dorian Gray (1890)","level":"general","topics":["Tuổi trẻ","Cảm xúc"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0150","text":"Beauty, real beauty, ends where an intellectual expression begins.","vi":"Vẻ đẹp đích thực chấm dứt nơi nét biểu cảm trí tuệ bắt đầu.","ex":"Lord Henry declares, “Beauty, real beauty, ends where an intellectual expression begins.”","exVi":"Lord Henry tuyên bố: “Vẻ đẹp đích thực chấm dứt nơi nét biểu cảm trí tuệ bắt đầu.”","src":"Oscar Wilde · The Picture of Dorian Gray (1890)","level":"general","topics":["Vẻ đẹp","Trí tuệ"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0151","text":"Details are always vulgar.","vi":"Những chi tiết vụn vặt lúc nào cũng tầm thường.","ex":"Lord Henry concludes, “Details are always vulgar.”","exVi":"Lord Henry kết luận: “Những chi tiết vụn vặt lúc nào cũng tầm thường.”","src":"Oscar Wilde · The Picture of Dorian Gray (1890)","level":"general","topics":["Quan sát","Lối sống"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0152","text":"The real drawback to marriage is that it makes one unselfish.","vi":"Điểm bất lợi thật sự của hôn nhân là nó khiến người ta bớt ích kỷ.","ex":"Lord Henry argues, “The real drawback to marriage is that it makes one unselfish.”","exVi":"Lord Henry lập luận: “Điểm bất lợi thật sự của hôn nhân là nó khiến người ta bớt ích kỷ.”","src":"Oscar Wilde · The Picture of Dorian Gray (1890)","level":"general","topics":["Hôn nhân","Tính cách"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0153","text":"It’s no use going back to yesterday, because I was a different person then.","vi":"Quay lại ngày hôm qua cũng chẳng ích gì, vì khi ấy tôi đã là một người khác.","ex":"Alice reflects, “It’s no use going back to yesterday, because I was a different person then.”","exVi":"Alice suy ngẫm: “Quay lại ngày hôm qua cũng chẳng ích gì, vì khi ấy tôi đã là một người khác.”","src":"Lewis Carroll · Alice’s Adventures in Wonderland (1865)","level":"general","topics":["Thay đổi","Thời gian"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0154","text":"We’re all mad here. I’m mad. You’re mad.","vi":"Ở đây ai cũng điên cả. Tôi điên. Cô cũng điên.","ex":"The Cat tells Alice, “We’re all mad here. I’m mad. You’re mad.”","exVi":"Mèo nói với Alice: “Ở đây ai cũng điên cả. Tôi điên. Cô cũng điên.”","src":"Lewis Carroll · Alice’s Adventures in Wonderland (1865)","level":"general","topics":["Khác biệt","Hài hước"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0155","text":"Take care of the sense, and the sounds will take care of themselves.","vi":"Hãy chú trọng ý nghĩa, rồi âm thanh sẽ tự ổn thỏa.","ex":"The Duchess advises, “Take care of the sense, and the sounds will take care of themselves.”","exVi":"Nữ Công tước khuyên: “Hãy chú trọng ý nghĩa, rồi âm thanh sẽ tự ổn thỏa.”","src":"Lewis Carroll · Alice’s Adventures in Wonderland (1865)","level":"general","topics":["Ngôn ngữ","Giao tiếp"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0156","text":"The time has come, the Walrus said, to talk of many things.","vi":"Hải mã nói: đã đến lúc bàn về nhiều chuyện.","ex":"The Walrus begins, “The time has come, the Walrus said, to talk of many things.”","exVi":"Hải mã mở lời: “Đã đến lúc bàn về nhiều chuyện.”","src":"Lewis Carroll · Through the Looking-Glass (1871)","level":"general","topics":["Giao tiếp","Thời điểm"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0157","text":"Begin at the beginning, and go on till you come to the end: then stop.","vi":"Hãy bắt đầu từ đầu, tiếp tục đến cuối, rồi dừng lại.","ex":"The King instructs, “Begin at the beginning, and go on till you come to the end: then stop.”","exVi":"Nhà vua chỉ dẫn: “Hãy bắt đầu từ đầu, tiếp tục đến cuối, rồi dừng lại.”","src":"Lewis Carroll · Alice’s Adventures in Wonderland (1865)","level":"general","topics":["Học tập","Trình tự"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0158","text":"When you’ve once said a thing, that fixes it, and you must take the consequences.","vi":"Một khi đã nói ra, lời ấy đã thành sự thật và bạn phải chịu hệ quả.","ex":"When you’ve once said a thing, that fixes it, and you must take the consequences.","exVi":"Nữ Hoàng Đỏ cảnh báo: “Một khi đã nói ra, lời ấy đã thành sự thật và bạn phải chịu hệ quả.”","src":"Lewis Carroll · Through the Looking-Glass (1871)","level":"general","topics":["Lời nói","Trách nhiệm"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0159","text":"The question is whether you can make words mean so many different things.","vi":"Câu hỏi là liệu bạn có thể khiến từ ngữ mang nhiều ý nghĩa khác nhau đến thế hay không.","ex":"Alice asks, “The question is whether you can make words mean so many different things.”","exVi":"Alice hỏi: “Câu hỏi là liệu từ ngữ có thể mang nhiều ý nghĩa khác nhau đến thế hay không.”","src":"Lewis Carroll · Through the Looking-Glass (1871)","level":"general","topics":["Ngôn ngữ","Sáng tạo"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0160","text":"Manners are not taught in lessons.","vi":"Phép lịch sự không thể chỉ học qua những bài học.","ex":"Alice replies, “Manners are not taught in lessons.”","exVi":"Alice đáp: “Phép lịch sự không thể chỉ học qua những bài học.”","src":"Lewis Carroll · Through the Looking-Glass (1871)","level":"general","topics":["Giáo dục","Cách cư xử"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0161","text":"All that we see or seem is but a dream within a dream.","vi":"Tất cả những gì ta thấy hay tưởng thấy chỉ là một giấc mơ lồng trong giấc mơ.","ex":"Poe writes, “All that we see or seem is but a dream within a dream.”","exVi":"Poe viết: “Tất cả những gì ta thấy hay tưởng thấy chỉ là một giấc mơ lồng trong giấc mơ.”","src":"Edgar Allan Poe · A Dream Within a Dream (1849)","level":"general","topics":["Giấc mơ","Nhận thức"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0162","text":"Take this kiss upon the brow!","vi":"Xin nhận nụ hôn này trên trán.","ex":"The speaker bids farewell, “Take this kiss upon the brow!”","exVi":"Nhân vật trữ tình từ biệt: “Xin nhận nụ hôn này trên trán.”","src":"Edgar Allan Poe · A Dream Within a Dream (1849)","level":"general","topics":["Tình yêu","Chia ly"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0163","text":"Deep into that darkness peering, long I stood there wondering, fearing.","vi":"Nhìn sâu vào bóng tối, tôi đứng đó thật lâu, vừa băn khoăn vừa sợ hãi.","ex":"The speaker recalls, “Deep into that darkness peering, long I stood there wondering, fearing.”","exVi":"Nhân vật trữ tình hồi tưởng: “Nhìn sâu vào bóng tối, tôi đứng đó thật lâu, vừa băn khoăn vừa sợ hãi.”","src":"Edgar Allan Poe · The Raven (1845)","level":"general","topics":["Sợ hãi","Đêm"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0164","text":"Once upon a midnight dreary, while I pondered, weak and weary.","vi":"Vào một đêm khuya buồn bã, khi tôi đang suy tư, kiệt sức và mỏi mòn.","ex":"The poem opens, “Once upon a midnight dreary, while I pondered, weak and weary.”","exVi":"Bài thơ mở đầu: “Vào một đêm khuya buồn bã, khi tôi đang suy tư, kiệt sức và mỏi mòn.”","src":"Edgar Allan Poe · The Raven (1845)","level":"general","topics":["Đêm","Cảm xúc"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0165","text":"And the Raven, never flitting, still is sitting, still is sitting.","vi":"Và con quạ vẫn không bay đi, cứ ngồi đó mãi, ngồi mãi.","ex":"Poe ends the stanza, “And the Raven, never flitting, still is sitting, still is sitting.”","exVi":"Poe kết đoạn thơ: “Và con quạ vẫn không bay đi, cứ ngồi đó mãi, ngồi mãi.”","src":"Edgar Allan Poe · The Raven (1845)","level":"general","topics":["Kiên trì","Bóng tối"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0166","text":"Is all that we see or seem but a dream within a dream?","vi":"Phải chăng mọi điều ta thấy hay tưởng thấy chỉ là một giấc mơ trong giấc mơ?","ex":"Poe asks, “Is all that we see or seem but a dream within a dream?”","exVi":"Poe đặt câu hỏi: “Phải chăng mọi điều ta thấy hay tưởng thấy chỉ là một giấc mơ trong giấc mơ?”","src":"Edgar Allan Poe · A Dream Within a Dream (1849)","level":"general","topics":["Giấc mơ","Triết học"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0167","text":"Dread remorse when you are tempted to err, Miss Eyre; remorse is the poison of life.","vi":"Hãy sợ sự hối hận khi bị cám dỗ làm điều sai; hối hận là chất độc của đời người.","ex":"Rochester warns, “Dread remorse when you are tempted to err, Miss Eyre; remorse is the poison of life.”","exVi":"Rochester cảnh báo: “Hãy sợ sự hối hận khi bị cám dỗ làm điều sai; hối hận là chất độc của đời người.”","src":"Charlotte Brontë · Jane Eyre (1847)","level":"general","topics":["Lựa chọn","Hối hận"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0168","text":"I would leave you in the old world, and betake myself to the new.","vi":"Tôi sẽ để cô lại ở thế giới cũ và tự mình tìm đến thế giới mới.","ex":"St. John declares, “I would leave you in the old world, and betake myself to the new.”","exVi":"St. John tuyên bố: “Tôi sẽ để cô lại ở thế giới cũ và tự mình tìm đến thế giới mới.”","src":"Charlotte Brontë · Jane Eyre (1847)","level":"general","topics":["Tự lập","Quan hệ"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0169","text":"Presentiments are strange things!","vi":"Linh cảm quả là điều kỳ lạ!","ex":"Jane reflects, “Presentiments are strange things!”","exVi":"Jane suy ngẫm: “Linh cảm quả là điều kỳ lạ!”","src":"Charlotte Brontë · Jane Eyre (1847)","level":"general","topics":["Linh cảm","Tâm lý"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0170","text":"I never laughed at presentiments in my life, because I have had strange ones of my own.","vi":"Tôi chưa từng cười nhạo linh cảm, vì bản thân cũng từng có những linh cảm kỳ lạ.","ex":"I never laughed at presentiments in my life, because I have had strange ones of my own.","exVi":"Tôi chưa từng cười nhạo linh cảm, vì bản thân cũng từng có những linh cảm kỳ lạ.","src":"Charlotte Brontë · Jane Eyre (1847)","level":"general","topics":["Linh cảm","Trải nghiệm"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0171","text":"The eagerness of a listener quickens the tongue of a narrator.","vi":"Sự chăm chú của người nghe khiến người kể chuyện thêm hào hứng.","ex":"Jane observes, “The eagerness of a listener quickens the tongue of a narrator.”","exVi":"Jane nhận xét: “Sự chăm chú của người nghe khiến người kể chuyện thêm hào hứng.”","src":"Charlotte Brontë · Jane Eyre (1847)","level":"general","topics":["Giao tiếp","Lắng nghe"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0172","text":"I was not a general philanthropist; but I bear a conscience.","vi":"Tôi không phải người làm từ thiện rộng khắp, nhưng tôi có lương tâm.","ex":"Rochester admits, “I was not a general philanthropist; but I bear a conscience.”","exVi":"Rochester thừa nhận: “Tôi không phải người làm từ thiện rộng khắp, nhưng tôi có lương tâm.”","src":"Charlotte Brontë · Jane Eyre (1847)","level":"general","topics":["Lòng tốt","Lương tâm"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0173","text":"I might say it to almost any one: but would it be true of almost any one?","vi":"Tôi có thể nói điều đó với gần như bất kỳ ai, nhưng liệu nó có đúng với họ không?","ex":"I might say it to almost any one: but would it be true of almost any one?","exVi":"Jane hỏi: “Tôi có thể nói điều đó với gần như bất kỳ ai, nhưng liệu nó có đúng với họ không?”","src":"Charlotte Brontë · Jane Eyre (1847)","level":"general","topics":["Sự thật","Tư duy"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0174","text":"I live in calm, looking to the end.","vi":"Tôi sống bình thản và hướng về kết cục cuối cùng.","ex":"Jane says, “I live in calm, looking to the end.”","exVi":"Jane nói: “Tôi sống bình thản và hướng về kết cục cuối cùng.”","src":"Charlotte Brontë · Jane Eyre (1847)","level":"general","topics":["Bình tĩnh","Hy vọng"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0175","text":"He made me love him without looking at me.","vi":"Anh ấy khiến tôi yêu mình mà chẳng cần nhìn tôi.","ex":"Jane confesses, “He made me love him without looking at me.”","exVi":"Jane thú nhận: “Anh ấy khiến tôi yêu mình mà chẳng cần nhìn tôi.”","src":"Charlotte Brontë · Jane Eyre (1847)","level":"general","topics":["Tình yêu","Cảm xúc"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0176","text":"I have strength yet for that.","vi":"Tôi vẫn còn đủ sức để làm điều đó.","ex":"Rochester insists, “I have strength yet for that.”","exVi":"Rochester quả quyết: “Tôi vẫn còn đủ sức để làm điều đó.”","src":"Charlotte Brontë · Jane Eyre (1847)","level":"general","topics":["Nghị lực","Thay đổi"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0177","text":"I have a right to get pleasure out of life.","vi":"Tôi có quyền tìm niềm vui trong cuộc sống.","ex":"Rochester declares, “I have a right to get pleasure out of life.”","exVi":"Rochester tuyên bố: “Tôi có quyền tìm niềm vui trong cuộc sống.”","src":"Charlotte Brontë · Jane Eyre (1847)","level":"general","topics":["Hạnh phúc","Quyền lựa chọn"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0178","text":"I can live alone, if self-respect, and circumstances require me so to do.","vi":"Nếu lòng tự trọng và hoàn cảnh đòi hỏi, tôi có thể sống một mình.","ex":"Jane resolves, “I can live alone, if self-respect, and circumstances require me so to do.”","exVi":"Jane tự nhủ: “Nếu lòng tự trọng và hoàn cảnh đòi hỏi, tôi có thể sống một mình.”","src":"Charlotte Brontë · Jane Eyre (1847)","level":"general","topics":["Tự trọng","Tự lập"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0179","text":"It is only necessary to make the thing difficult to attain.","vi":"Chỉ cần khiến một điều khó đạt được là người ta sẽ khao khát nó.","ex":"The narrator observes, “It is only necessary to make the thing difficult to attain.”","exVi":"Người kể chuyện nhận xét: “Chỉ cần khiến một điều khó đạt được là người ta sẽ khao khát nó.”","src":"Mark Twain · The Adventures of Tom Sawyer (1876)","level":"general","topics":["Động lực","Tâm lý"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0180","text":"Work consists of whatever a body is obliged to do.","vi":"Công việc là bất cứ điều gì ta buộc phải làm.","ex":"The narrator jokes, “Work consists of whatever a body is obliged to do.”","exVi":"Người kể chuyện hóm hỉnh nói: “Công việc là bất cứ điều gì ta buộc phải làm.”","src":"Mark Twain · The Adventures of Tom Sawyer (1876)","level":"general","topics":["Công việc","Cách nhìn"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0181","text":"Play consists of whatever a body is not obliged to do.","vi":"Vui chơi là những điều ta không bị buộc phải làm.","ex":"The narrator adds, “Play consists of whatever a body is not obliged to do.”","exVi":"Người kể chuyện nói thêm: “Vui chơi là những điều ta không bị buộc phải làm.”","src":"Mark Twain · The Adventures of Tom Sawyer (1876)","level":"general","topics":["Giải trí","Cách nhìn"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0182","text":"Does a boy get a chance to whitewash a fence every day?","vi":"Đâu phải ngày nào một cậu bé cũng có cơ hội quét vôi hàng rào?","ex":"Tom asks, “Does a boy get a chance to whitewash a fence every day?”","exVi":"Tom hỏi: “Đâu phải ngày nào một cậu bé cũng có cơ hội quét vôi hàng rào?”","src":"Mark Twain · The Adventures of Tom Sawyer (1876)","level":"general","topics":["Công việc","Thái độ"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0183","text":"Human beings can be awful cruel to one another.","vi":"Con người đôi khi có thể đối xử với nhau vô cùng tàn nhẫn.","ex":"Huck reflects, “Human beings can be awful cruel to one another.”","exVi":"Huck suy ngẫm: “Con người đôi khi có thể đối xử với nhau vô cùng tàn nhẫn.”","src":"Mark Twain · Adventures of Huckleberry Finn (1884)","level":"general","topics":["Lòng trắc ẩn","Quan hệ xã hội"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0184","text":"All right, then, I'll GO to hell.","vi":"Được thôi, vậy thì tôi sẽ xuống địa ngục.","ex":"Huck decides, “All right, then, I'll GO to hell.”","exVi":"Huck quyết định: “Được thôi, vậy thì tôi sẽ xuống địa ngục.”","src":"Mark Twain · Adventures of Huckleberry Finn (1884)","level":"general","topics":["Lương tâm","Lựa chọn"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0185","text":"Two things cannot be in one place.","vi":"Hai điều không thể cùng tồn tại ở một chỗ.","ex":"The story states, “Two things cannot be in one place.”","exVi":"Câu chuyện viết: “Hai điều không thể cùng tồn tại ở một chỗ.”","src":"Frances Hodgson Burnett · The Secret Garden (1911)","level":"general","topics":["Suy nghĩ","Thói quen"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0186","text":"Where you tend a rose, my lad, a thistle cannot grow.","vi":"Nơi con chăm một đóa hồng, cỏ kế sẽ chẳng thể mọc.","ex":"Dickon recites, “Where you tend a rose, my lad, a thistle cannot grow.”","exVi":"Dickon đọc: “Nơi con chăm một đóa hồng, cỏ kế sẽ chẳng thể mọc.”","src":"Frances Hodgson Burnett · The Secret Garden (1911)","level":"general","topics":["Thiên nhiên","Sự chăm sóc"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0187","text":"It's a poor sort of memory that only works backwards.","vi":"Đó là kiểu trí nhớ kém cỏi nếu chỉ hoạt động theo chiều ngược lại.","ex":"The Queen remarks, “It's a poor sort of memory that only works backwards.”","exVi":"Nữ hoàng nhận xét: “Đó là kiểu trí nhớ kém cỏi nếu chỉ hoạt động theo chiều ngược lại.”","src":"Lewis Carroll · Through the Looking-Glass (1871)","level":"general","topics":["Ngôn ngữ","Giao tiếp"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0188","text":"I like adventures, and I'm going to find some.","vi":"Tôi thích những cuộc phiêu lưu, và tôi sẽ tự tìm lấy chúng.","ex":"Jo declares, “I like adventures, and I'm going to find some.”","exVi":"Jo tuyên bố: “Tôi thích những cuộc phiêu lưu, và tôi sẽ tự tìm lấy chúng.”","src":"Louisa May Alcott · Little Women (1868)","level":"general","topics":["Phiêu lưu","Sở thích"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0189","text":"Marilla, isn't it nice to think that tomorrow is a new day with no mistakes in it yet?","vi":"Marilla, nghĩ rằng ngày mai là một ngày mới chưa có sai lầm nào, chẳng phải thật hay sao?","ex":"Marilla, isn't it nice to think that tomorrow is a new day with no mistakes in it yet?","exVi":"Marilla, nghĩ rằng ngày mai là một ngày mới chưa có sai lầm nào, chẳng phải thật hay sao?","src":"L. M. Montgomery · Anne of Green Gables (1908)","level":"general","topics":["Ước mơ","Thành công"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0190","text":"It's so dreadful to be poor!","vi":"Nghèo khó thật đáng sợ!","ex":"Jo sighs, “It's so dreadful to be poor!”","exVi":"Jo thở dài: “Nghèo khó thật đáng sợ!”","src":"Louisa May Alcott · Little Women (1868)","level":"general","topics":["Tiền bạc","Cảm xúc"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0191","text":"I do wonder if any of us will ever get our wishes.","vi":"Tôi tự hỏi liệu có ai trong chúng ta rồi sẽ đạt được ước nguyện không.","ex":"Laurie wonders, “I do wonder if any of us will ever get our wishes.”","exVi":"Laurie tự hỏi: “Tôi tự hỏi liệu có ai trong chúng ta rồi sẽ đạt được ước nguyện không.”","src":"Louisa May Alcott · Little Women (1868)","level":"general","topics":["Ước mơ","Tương lai"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0192","text":"Money is a needful and precious thing, and when well used, a noble thing.","vi":"Tiền là thứ cần thiết và quý giá; khi được dùng đúng cách, nó cũng thật cao quý.","ex":"Mrs. March explains, “Money is a needful and precious thing, and when well used, a noble thing.”","exVi":"Bà March giải thích: “Tiền là thứ cần thiết và quý giá; khi được dùng đúng cách, nó cũng thật cao quý.”","src":"Louisa May Alcott · Little Women (1868)","level":"general","topics":["Tiền bạc","Giá trị sống"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0193","text":"Now, here, you see, it takes all the running you can do, to keep in the same place.","vi":"Ở đây, muốn đứng yên tại chỗ thôi, bạn cũng phải chạy hết sức mình.","ex":"Now, here, you see, it takes all the running you can do, to keep in the same place.","exVi":"Nữ hoàng giải thích: “Ở đây, muốn đứng yên tại chỗ thôi, bạn cũng phải chạy hết sức mình.”","src":"Lewis Carroll · Through the Looking-Glass (1871)","level":"general","topics":["Nỗ lực","Thay đổi"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0194","text":"That's the effect of living backwards.","vi":"Đó là tác động của việc sống theo chiều ngược lại.","ex":"The Queen remarks, “That's the effect of living backwards.”","exVi":"Nữ hoàng nhận xét: “Đó là tác động của việc sống theo chiều ngược lại.”","src":"Lewis Carroll · Through the Looking-Glass (1871)","level":"general","topics":["Thời gian","Hài hước"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0195","text":"But if you stay in a room you never see things.","vi":"Nhưng nếu cứ ở trong phòng, bạn sẽ chẳng bao giờ nhìn thấy mọi thứ bên ngoài.","ex":"Colin observes, “But if you stay in a room you never see things.”","exVi":"Colin nhận xét: “Nhưng nếu cứ ở trong phòng, bạn sẽ chẳng bao giờ nhìn thấy mọi thứ bên ngoài.”","src":"Frances Hodgson Burnett · The Secret Garden (1911)","level":"general","topics":["Trải nghiệm","Khám phá"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0196","text":"It is the sun shining on the rain and the rain falling on the sunshine.","vi":"Đó là mặt trời chiếu trên cơn mưa và mưa rơi xuống ánh nắng.","ex":"Mary describes spring, “It is the sun shining on the rain and the rain falling on the sunshine.”","exVi":"Mary miêu tả mùa xuân: “Đó là mặt trời chiếu trên cơn mưa và mưa rơi xuống ánh nắng.”","src":"Frances Hodgson Burnett · The Secret Garden (1911)","level":"general","topics":["Thiên nhiên","Mùa xuân"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0197","text":"Isn't it a splendid thing that there are mornings?","vi":"Chẳng phải thật tuyệt khi mỗi ngày đều có buổi sáng sao?","ex":"Anne asks, “Isn't it a splendid thing that there are mornings?”","exVi":"Anne hỏi: “Chẳng phải thật tuyệt khi mỗi ngày đều có buổi sáng sao?”","src":"L. M. Montgomery · Anne of Green Gables (1908)","level":"general","topics":["Hy vọng","Thói quen"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0198","text":"There is no use in loving things if you have to be torn from them, is there?","vi":"Yêu quý một điều gì rồi phải rời xa nó thì ích gì, phải không?","ex":"There is no use in loving things if you have to be torn from them, is there?","exVi":"Anne hỏi: “Yêu quý một điều gì rồi phải rời xa nó thì ích gì, phải không?”","src":"L. M. Montgomery · Anne of Green Gables (1908)","level":"general","topics":["Tình cảm","Gắn bó"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0199","text":"I'm so glad I live in a world where there are Octobers.","vi":"Tôi thật vui vì mình sống trong một thế giới có những tháng Mười.","ex":"Anne exclaims, “I'm so glad I live in a world where there are Octobers.”","exVi":"Anne reo lên: “Tôi thật vui vì mình sống trong một thế giới có những tháng Mười.”","src":"L. M. Montgomery · Anne of Green Gables (1908)","level":"general","topics":["Thiên nhiên","Biết ơn"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0200","text":"There is no living thing that is not afraid when it faces danger.","vi":"Không sinh vật nào không biết sợ khi đối diện với hiểm nguy.","ex":"The Wizard reminds the Lion, “There is no living thing that is not afraid when it faces danger.”","exVi":"Pháp sư nhắc Sư Tử: “Không sinh vật nào không biết sợ khi đối diện với hiểm nguy.”","src":"L. Frank Baum · The Wonderful Wizard of Oz (1900)","level":"general","topics":["Nỗi sợ","Can đảm"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0201","text":"Experience is the only thing that brings knowledge.","vi":"Trải nghiệm là điều duy nhất đem lại hiểu biết.","ex":"Oz tells the Scarecrow, “Experience is the only thing that brings knowledge.”","exVi":"Oz nói với Bù Nhìn: “Trải nghiệm là điều duy nhất đem lại hiểu biết.”","src":"L. Frank Baum · The Wonderful Wizard of Oz (1900)","level":"general","topics":["Trải nghiệm","Học hỏi"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0202","text":"I'm really a very good man, but I'm a very bad Wizard, I must admit.","vi":"Thú thật, tôi là người tốt, nhưng lại là một pháp sư rất tệ.","ex":"Oz admits, “I'm really a very good man, but I'm a very bad Wizard, I must admit.”","exVi":"Oz thú nhận: “Thú thật, tôi là người tốt, nhưng lại là một pháp sư rất tệ.”","src":"L. Frank Baum · The Wonderful Wizard of Oz (1900)","level":"general","topics":["Tự nhận thức","Hài hước"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0203","text":"I haven't the heart to harm even a Witch.","vi":"Tôi chẳng nỡ làm hại ngay cả một phù thủy.","ex":"The Tin Woodman says, “I haven't the heart to harm even a Witch.”","exVi":"Người Thiếc nói: “Tôi chẳng nỡ làm hại ngay cả một phù thủy.”","src":"L. Frank Baum · The Wonderful Wizard of Oz (1900)","level":"general","topics":["Lòng tốt","Cảm xúc"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0204","text":"The course of true love never did run smooth.","vi":"Tình yêu chân thành hiếm khi đi qua một hành trình bằng phẳng.","ex":"Their path was difficult because the course of true love never did run smooth.","exVi":"Đường tình của họ đầy trắc trở, bởi tình yêu chân thành hiếm khi suôn sẻ.","src":"William Shakespeare · A Midsummer Night’s Dream (1596)","level":"general","topics":["Tình yêu","Trải nghiệm"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0205","text":"Love looks not with the eyes, but with the mind.","vi":"Tình yêu nhìn bằng tâm trí chứ không chỉ bằng đôi mắt.","ex":"Love looks not with the eyes, but with the mind, the poet argues.","exVi":"Nhà thơ cho rằng tình yêu nhìn bằng tâm trí chứ không chỉ bằng đôi mắt.","src":"William Shakespeare · A Midsummer Night’s Dream (1596)","level":"general","topics":["Tình yêu","Cách nhìn"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0206","text":"We know what we are, but know not what we may be.","vi":"Ta biết mình đang là ai, nhưng chưa biết mình có thể trở thành người thế nào.","ex":"We know what we are, but know not what we may be, Ophelia says.","exVi":"Ophelia nói rằng ta biết mình đang là ai, nhưng chưa biết mình có thể trở thành người thế nào.","src":"William Shakespeare · Hamlet (1603)","level":"general","topics":["Tự nhận thức","Tương lai"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0207","text":"If music be the food of love, play on.","vi":"Nếu âm nhạc nuôi dưỡng tình yêu, hãy cứ tiếp tục chơi nhạc.","ex":"If music be the food of love, play on; let the melody continue.","exVi":"Nếu âm nhạc nuôi dưỡng tình yêu, hãy cứ chơi tiếp và để giai điệu ngân vang.","src":"William Shakespeare · Twelfth Night (1601)","level":"general","topics":["Âm nhạc","Tình yêu"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0208","text":"The quality of mercy is not strained.","vi":"Lòng khoan dung chân thành không thể bị ép buộc.","ex":"The quality of mercy is not strained; it can reach both giver and receiver.","exVi":"Lòng khoan dung chân thành không thể bị ép buộc; nó có ích cho cả người cho lẫn người nhận.","src":"William Shakespeare · The Merchant of Venice (1600)","level":"general","topics":["Lòng tốt","Công lý"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0209","text":"The miserable have no other medicine but only hope.","vi":"Với người khốn khó, hy vọng là phương thuốc duy nhất còn lại.","ex":"The miserable have no other medicine but only hope, he reminded himself.","exVi":"Anh tự nhắc rằng với người khốn khó, hy vọng là phương thuốc duy nhất còn lại.","src":"William Shakespeare · Measure for Measure (1604)","level":"general","topics":["Hy vọng","Khó khăn"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0210","text":"All things are ready, if our minds be so.","vi":"Mọi thứ đều đã sẵn sàng nếu tâm trí chúng ta cũng sẵn sàng.","ex":"All things are ready, if our minds be so, the captain announced.","exVi":"Vị chỉ huy tuyên bố rằng mọi thứ đã sẵn sàng nếu tâm trí mọi người cũng sẵn sàng.","src":"William Shakespeare · Henry V (1599)","level":"general","topics":["Sẵn sàng","Tinh thần"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0211","text":"Love all, trust a few, do wrong to none.","vi":"Hãy yêu thương mọi người, chỉ tin một số người và đừng làm hại ai.","ex":"Her mother advised, “Love all, trust a few, do wrong to none.”","exVi":"Mẹ cô khuyên: “Hãy yêu thương mọi người, chỉ tin một số người và đừng làm hại ai.”","src":"William Shakespeare · All’s Well That Ends Well (1603)","level":"general","topics":["Quan hệ","Đạo đức"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0212","text":"Sweet are the uses of adversity.","vi":"Nghịch cảnh đôi khi đem lại những bài học quý giá.","ex":"After the setback, she recalled that sweet are the uses of adversity.","exVi":"Sau thất bại, cô nhớ rằng nghịch cảnh đôi khi đem lại những bài học quý giá.","src":"William Shakespeare · As You Like It (1599)","level":"general","topics":["Nghịch cảnh","Học hỏi"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0213","text":"There are more things in heaven and earth, Horatio, than are dreamt of in your philosophy.","vi":"Horatio, trên trời dưới đất còn nhiều điều vượt xa những gì triết học của anh hình dung.","ex":"There are more things in heaven and earth, Horatio, than are dreamt of in your philosophy.","exVi":"Horatio, trên trời dưới đất còn nhiều điều vượt xa những gì triết học của anh hình dung.","src":"William Shakespeare · Hamlet (1603)","level":"general","topics":["Triết học","Khám phá"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0214","text":"How poor are they that have not patience!","vi":"Thật đáng thương cho những ai không có lòng kiên nhẫn.","ex":"How poor are they that have not patience! Iago urges Roderigo to wait.","exVi":"Iago giục Roderigo chờ đợi và nhận xét: “Thật đáng thương cho những ai không có lòng kiên nhẫn.”","src":"William Shakespeare · Othello (1603)","level":"general","topics":["Kiên nhẫn","Khó khăn"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0215","text":"The web of our life is of a mingled yarn, good and ill together.","vi":"Cuộc đời được dệt từ cả điều tốt lẫn điều không hay.","ex":"The web of our life is of a mingled yarn, good and ill together, he reflects.","exVi":"Anh suy ngẫm rằng cuộc đời được dệt từ cả điều tốt lẫn điều không hay.","src":"William Shakespeare · All’s Well That Ends Well (1603)","level":"general","topics":["Đời sống","Thăng trầm"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0216","text":"It is excellent to have a giant’s strength, but it is tyrannous to use it like a giant.","vi":"Có sức mạnh phi thường thật tuyệt, nhưng dùng nó để áp bức người khác là chuyên quyền.","ex":"It is excellent to have a giant’s strength, but it is tyrannous to use it like a giant.","exVi":"Có sức mạnh phi thường thật tuyệt, nhưng dùng nó để áp bức người khác là chuyên quyền.","src":"William Shakespeare · Measure for Measure (1604)","level":"general","topics":["Quyền lực","Công bằng"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0217","text":"Our revels now are ended.","vi":"Cuộc vui của chúng ta đến đây là kết thúc.","ex":"Prospero says, “Our revels now are ended.”","exVi":"Prospero nói: “Cuộc vui của chúng ta đến đây là kết thúc.”","src":"William Shakespeare · The Tempest (1611)","level":"general","topics":["Kết thúc","Sân khấu"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0218","text":"Be not afeard; the isle is full of noises.","vi":"Đừng sợ; hòn đảo này đầy những âm thanh.","ex":"Be not afeard; the isle is full of noises.","exVi":"Caliban nói rằng hòn đảo đầy những âm thanh và không đáng sợ.","src":"William Shakespeare · The Tempest (1611)","level":"general","topics":["Nỗi sợ","Thiên nhiên"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0219","text":"Misery acquaints a man with strange bedfellows.","vi":"Cảnh khốn khó có thể khiến người ta phải chung cảnh với những người lạ lùng.","ex":"Misery acquaints a man with strange bedfellows.","exVi":"Gian khó có thể khiến người ta phải chung cảnh với những người xa lạ.","src":"William Shakespeare · The Tempest (1611)","level":"general","topics":["Khó khăn","Quan hệ xã hội"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0220","text":"We few, we happy few, we band of brothers.","vi":"Chúng ta, những người ít ỏi nhưng hạnh phúc, là một tập thể gắn bó.","ex":"We few, we happy few, we band of brothers.","exVi":"Nhà vua gọi những người đồng đội ít ỏi của mình là một tập thể gắn bó.","src":"William Shakespeare · Henry V (1599)","level":"general","topics":["Tình bạn","Cộng đồng"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0221","text":"Once more unto the breach, dear friends, once more.","vi":"Các bạn thân mến, hãy cùng tiến lên chỗ đột phá thêm một lần nữa.","ex":"Once more unto the breach, dear friends, once more.","exVi":"Nhà vua động viên đồng đội tiến lên thêm một lần nữa.","src":"William Shakespeare · Henry V (1599)","level":"general","topics":["Can đảm","Hợp tác"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0222","text":"The game's afoot; follow your spirit.","vi":"Cuộc chơi đã bắt đầu; hãy làm theo tinh thần của mình.","ex":"The game's afoot; follow your spirit.","exVi":"Nhà vua thúc giục binh sĩ hành động theo tinh thần của họ.","src":"William Shakespeare · Henry V (1599)","level":"general","topics":["Hành động","Động lực"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0223","text":"Good name in man and woman is the immediate jewel of their souls.","vi":"Danh dự là báu vật quý giá nhất trong tâm hồn mỗi người.","ex":"Good name in man and woman is the immediate jewel of their souls.","exVi":"Iago ví danh dự của con người như báu vật trong tâm hồn.","src":"William Shakespeare · Othello (1603)","level":"general","topics":["Danh tiếng","Đạo đức"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0224","text":"One that loved not wisely, but too well.","vi":"Một người yêu không khôn ngoan, nhưng đã yêu hết lòng.","ex":"One that loved not wisely, but too well.","exVi":"Othello tự mô tả mình là người đã yêu hết lòng nhưng không sáng suốt.","src":"William Shakespeare · Othello (1603)","level":"general","topics":["Tình yêu","Tự nhìn nhận"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0225","text":"Life's but a walking shadow; a poor player.","vi":"Đời người chẳng khác nào cái bóng lướt qua; một diễn viên tầm thường.","ex":"Life's but a walking shadow; a poor player.","exVi":"Macbeth ví cuộc đời với một cái bóng và một diễn viên tầm thường.","src":"William Shakespeare · Macbeth (1606)","level":"general","topics":["Đời sống","Thời gian"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0226","text":"Beauty is truth, truth beauty.","vi":"Vẻ đẹp chính là chân lý, và chân lý chính là vẻ đẹp.","ex":"Beauty is truth, truth beauty.","exVi":"Keats cô đọng suy ngẫm về mối liên hệ giữa cái đẹp và chân lý.","src":"John Keats · Ode on a Grecian Urn (1820)","level":"general","topics":["Nhận thức","Giao tiếp"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0227","text":"Uneasy lies the head that wears a crown.","vi":"Người gánh vác quyền lực thường khó tránh khỏi lo âu.","ex":"Uneasy lies the head that wears a crown.","exVi":"Vua Henry suy ngẫm về nỗi lo của người đứng đầu đất nước.","src":"William Shakespeare · Henry IV, Part 2 (1597)","level":"general","topics":["Trách nhiệm","Áp lực"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0228","text":"I have been half in love with easeful Death.","vi":"Đã có lúc tôi gần như say mê cái chết êm đềm.","ex":"I have been half in love with easeful Death.","exVi":"Keats diễn tả khoảnh khắc thi sĩ bị cái chết êm đềm quyến rũ.","src":"John Keats · Ode to a Nightingale (1819)","level":"general","topics":["Quyết định","Tự chủ"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0229","text":"To strive, to seek, to find, and not to yield.","vi":"Nỗ lực, tìm kiếm, khám phá và không đầu hàng.","ex":"To strive, to seek, to find, and not to yield.","exVi":"Tennyson khép lại bài thơ bằng lời kêu gọi tiếp tục nỗ lực và không đầu hàng.","src":"Alfred, Lord Tennyson · Ulysses (1842)","level":"general","topics":["Kiên trì","Động lực"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0230","text":"Tho' much is taken, much abides.","vi":"Dẫu đã mất đi nhiều điều, vẫn còn nhiều thứ ở lại.","ex":"Tho' much is taken, much abides.","exVi":"Tennyson nhấn mạnh rằng sau mất mát, con người vẫn còn điều để gìn giữ.","src":"Alfred, Lord Tennyson · Ulysses (1842)","level":"general","topics":["Hy vọng","Sức chịu đựng"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0231","text":"Come, my friends, 'tis not too late to seek a newer world.","vi":"Các bạn ơi, vẫn chưa muộn để cùng tìm kiếm một thế giới mới.","ex":"Come, my friends, 'tis not too late to seek a newer world.","exVi":"Người kể mời bạn đồng hành tìm kiếm một thế giới mới dù tuổi đã cao.","src":"Alfred, Lord Tennyson · Ulysses (1842)","level":"general","topics":["Phiêu lưu","Tương lai"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0232","text":"A thing of beauty is a joy for ever.","vi":"Một điều đẹp đẽ có thể đem lại niềm vui lâu dài.","ex":"A thing of beauty is a joy for ever.","exVi":"Keats mở đầu bài thơ bằng suy ngẫm rằng vẻ đẹp có thể đem lại niềm vui bền lâu.","src":"John Keats · Endymion (1818)","level":"general","topics":["Vẻ đẹp","Hạnh phúc"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0233","text":"Thou wast not born for death, immortal Bird!","vi":"Hỡi chú chim bất tử, ngươi đâu được sinh ra để chết!","ex":"Thou wast not born for death, immortal Bird!","exVi":"Keats đối chiếu tuổi thọ ngắn ngủi của con người với khúc hát như trường tồn của chim họa mi.","src":"John Keats · Ode to a Nightingale (1819)","level":"general","topics":["Âm nhạc","Tưởng tượng"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0234","text":"Look on my works, ye Mighty, and despair!","vi":"Hỡi những kẻ quyền thế, hãy nhìn công trình của ta mà tuyệt vọng đi!","ex":"Look on my works, ye Mighty, and despair!","exVi":"Shelley dùng lời khắc trên tượng đài để làm nổi bật sự phù du của quyền lực.","src":"Percy Bysshe Shelley · Ozymandias (1818)","level":"general","topics":["Quyền lực","Thời gian"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0235","text":"The world is too much with us; late and soon.","vi":"Thế giới vật chất chiếm quá nhiều tâm trí ta, từ sớm đến muộn.","ex":"The world is too much with us; late and soon.","exVi":"Wordsworth phê phán lối sống quá bận tâm đến việc kiếm tiền và tiêu dùng.","src":"William Wordsworth · The World Is Too Much with Us (1807)","level":"general","topics":["Lối sống","Môi trường sống"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0236","text":"The best portion of a good man's life is his little, nameless, unremembered acts of kindness and love.","vi":"Phần đẹp nhất trong đời người tốt là những hành động tử tế và yêu thương nhỏ bé, thầm lặng.","ex":"The best portion of a good man's life is his little, nameless, unremembered acts of kindness and love.","exVi":"Wordsworth trân trọng những việc tử tế nhỏ bé mà người khác có thể không nhớ đến.","src":"William Wordsworth · Lines Written a Few Miles above Tintern Abbey (1798)","level":"general","topics":["Lòng tốt","Đạo đức"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0237","text":"To see the world in a grain of sand, and a heaven in a wild flower.","vi":"Nhìn thấy cả thế giới trong hạt cát và cả thiên đường trong một bông hoa dại.","ex":"To see the world in a grain of sand, and a heaven in a wild flower.","exVi":"Blake gợi mở cách nhìn thấy điều bao la trong những vật nhỏ bé quanh ta.","src":"William Blake · Auguries of Innocence (c. 1803)","level":"general","topics":["Cách nhìn","Thiên nhiên"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0238","text":"Let us, then, be up and doing, with a heart for any fate.","vi":"Vậy hãy đứng dậy hành động, với một trái tim sẵn sàng đón nhận mọi điều.","ex":"Let us, then, be up and doing, with a heart for any fate.","exVi":"Longfellow khích lệ người đọc chủ động hành động và can đảm đón nhận tương lai.","src":"Henry Wadsworth Longfellow · A Psalm of Life (1838)","level":"general","topics":["Chủ động","Can đảm"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0239","text":"You pierce my soul. I am half agony, half hope.","vi":"Em làm tâm hồn anh rung động; anh vừa đau khổ vừa nuôi hy vọng.","ex":"Wentworth writes, “You pierce my soul. I am half agony, half hope.”","exVi":"Trong lá thư, Wentworth thú nhận tình yêu cùng nỗi lo mất Anne.","src":"Jane Austen · Persuasion (1818)","level":"general","topics":["Tình yêu","Hy vọng"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0240","text":"I can listen no longer in silence.","vi":"Tôi không thể tiếp tục im lặng lắng nghe nữa.","ex":"Anne begins, “I can listen no longer in silence.”","exVi":"Anne mở đầu lá thư bằng lời khẳng định rằng cô không thể im lặng thêm.","src":"Jane Austen · Persuasion (1818)","level":"general","topics":["Giao tiếp","Can đảm"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0241","text":"My idea of good company, Mr Elliot, is the company of clever, well-informed people.","vi":"Theo tôi, bạn đồng hành thú vị là những người thông minh và hiểu biết.","ex":"Anne says, “My idea of good company, Mr Elliot, is the company of clever, well-informed people.”","exVi":"Anne giải thích rằng cô quý trọng trí tuệ và cuộc trò chuyện hơn địa vị.","src":"Jane Austen · Persuasion (1818)","level":"general","topics":["Tình bạn","Học tập"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0242","text":"loving longest, when existence or when hope is gone.","vi":"vẫn yêu thương lâu bền nhất, ngay cả khi cuộc đời hoặc hy vọng sắp hết.","ex":"Anne defends “loving longest, when existence or when hope is gone.”","exVi":"Anne cho rằng tình yêu của phụ nữ có thể bền bỉ qua cả mất mát.","src":"Jane Austen · Persuasion (1818)","level":"general","topics":["Tình yêu","Bền bỉ"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0243","text":"the company of clever, well-informed people","vi":"những người thông minh và giàu hiểu biết ở bên mình","ex":"Anne prefers “the company of clever, well-informed people.”","exVi":"Với Anne, sự hiểu biết làm cho một cuộc gặp gỡ trở nên đáng giá.","src":"Jane Austen · Persuasion (1818)","level":"general","topics":["Quan hệ xã hội","Học tập"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0244","text":"I am Heathcliff!","vi":"Tôi chính là Heathcliff!","ex":"Catherine cries, “I am Heathcliff!”","exVi":"Catherine diễn tả mối gắn bó sâu sắc giữa cô và Heathcliff.","src":"Emily Brontë · Wuthering Heights (1847)","level":"general","topics":["Tình yêu","Bản sắc"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0245","text":"He’s more myself than I am.","vi":"Anh ấy còn thuộc về con người tôi hơn chính bản thân tôi.","ex":"He’s more myself than I am.","exVi":"Catherine mô tả sự đồng điệu gần như không thể tách rời với Heathcliff.","src":"Emily Brontë · Wuthering Heights (1847)","level":"general","topics":["Tình yêu","Bản sắc"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0246","text":"I cannot live without my life! I cannot live without my soul!","vi":"Tôi không thể sống thiếu cuộc đời mình! Tôi không thể sống thiếu linh hồn mình!","ex":"Heathcliff cries, “I cannot live without my life! I cannot live without my soul!”","exVi":"Heathcliff đau đớn trước ý nghĩ phải sống khi Catherine không còn.","src":"Emily Brontë · Wuthering Heights (1847)","level":"general","topics":["Mất mát","Tình yêu"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0247","text":"If all else perished, and he remained, I should still continue to be.","vi":"Nếu mọi thứ biến mất mà anh vẫn còn, tôi vẫn sẽ tiếp tục tồn tại.","ex":"Catherine imagines, “If all else perished, and he remained, I should still continue to be.”","exVi":"Catherine tin rằng sự hiện diện của Heathcliff gắn liền với chính sự tồn tại của cô.","src":"Emily Brontë · Wuthering Heights (1847)","level":"general","topics":["Tình yêu","Sự sống"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0248","text":"I wish I were a girl again, half savage and hardy, and free.","vi":"Tôi ước mình lại là cô gái hoang dã, mạnh mẽ và tự do ngày nào.","ex":"Catherine wishes, “I wish I were a girl again, half savage and hardy, and free.”","exVi":"Catherine nhớ quãng đời tự do, khỏe khoắn trước những ràng buộc hiện tại.","src":"Emily Brontë · Wuthering Heights (1847)","level":"general","topics":["Tự do","Tuổi trẻ"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0249","text":"I have not broken your heart—you have broken it; and in breaking it, you have broken mine.","vi":"Tôi không làm tan nát trái tim em; chính em đã làm vậy, và cũng khiến tim tôi tan vỡ.","ex":"I have not broken your heart—you have broken it; and in breaking it, you have broken mine.","exVi":"Heathcliff vừa trách móc vừa bộc lộ nỗi đau vì tình yêu đổ vỡ.","src":"Emily Brontë · Wuthering Heights (1847)","level":"general","topics":["Mất mát","Quan hệ"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0250","text":"Life appears to me too short to be spent in nursing animosity.","vi":"Tôi thấy đời người quá ngắn để cứ nuôi dưỡng lòng oán giận.","ex":"Jane reflects, “Life appears to me too short to be spent in nursing animosity.”","exVi":"Jane khuyên Helen đừng để sự oán giận chiếm mất thời gian sống quý giá.","src":"Charlotte Brontë · Jane Eyre (1847)","level":"general","topics":["Tha thứ","Thời gian"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0251","text":"Do you think I am an automaton?—a machine without feelings?","vi":"Anh nghĩ tôi là một cỗ máy, không có cảm xúc sao?","ex":"Jane asks, “Do you think I am an automaton?—a machine without feelings?”","exVi":"Jane phản kháng khi Rochester xem nhẹ cảm xúc và phẩm giá của cô.","src":"Charlotte Brontë · Jane Eyre (1847)","level":"general","topics":["Cảm xúc","Bình đẳng"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0252","text":"I am a free human being with an independent will.","vi":"Tôi là một con người tự do với ý chí độc lập.","ex":"Jane declares, “I am a free human being with an independent will.”","exVi":"Jane khẳng định cô có quyền tự quyết định cuộc đời mình.","src":"Charlotte Brontë · Jane Eyre (1847)","level":"general","topics":["Tự do","Bình đẳng"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0253","text":"I have as much soul as you, and full as much heart!","vi":"Tôi cũng có tâm hồn và trái tim sâu sắc chẳng kém gì anh!","ex":"Jane insists, “I have as much soul as you, and full as much heart!”","exVi":"Jane nhắc Rochester rằng họ bình đẳng về cảm xúc và phẩm giá.","src":"Charlotte Brontë · Jane Eyre (1847)","level":"general","topics":["Bình đẳng","Cảm xúc"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0254","text":"I am not talking to you now through the medium of custom, conventionalities, nor even mortal flesh.","vi":"Lúc này, tôi không nói với anh qua những phép tắc hay hình hài trần thế.","ex":"I am not talking to you now through the medium of custom, conventionalities, nor even mortal flesh.","exVi":"Jane nói về sự kết nối tinh thần vượt lên trên những khuôn phép xã hội.","src":"Charlotte Brontë · Jane Eyre (1847)","level":"general","topics":["Giao tiếp","Tình yêu"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0255","text":"I cannot rest from travel.","vi":"Tôi không thể ngừng lên đường và khám phá.","ex":"Ulysses says, “I cannot rest from travel.”","exVi":"Ulysses vẫn khao khát tiếp tục hành trình dù đã lớn tuổi.","src":"Alfred, Lord Tennyson · Ulysses (1842)","level":"general","topics":["Du lịch","Khám phá"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0256","text":"How dull it is to pause, to make an end.","vi":"Dừng lại, khép lại mọi thứ thật buồn tẻ biết bao.","ex":"Ulysses wonders, “How dull it is to pause, to make an end.”","exVi":"Ulysses cảm thấy cuộc sống mất đi sức sống nếu con người ngừng tiến bước.","src":"Alfred, Lord Tennyson · Ulysses (1842)","level":"general","topics":["Động lực","Tuổi tác"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0257","text":"Old age hath yet his honour and his toil.","vi":"Tuổi già vẫn có phẩm giá và công việc của riêng mình.","ex":"Ulysses says, “Old age hath yet his honour and his toil.”","exVi":"Nhà vua cho rằng tuổi già vẫn có thể sống có ích và đáng trọng.","src":"Alfred, Lord Tennyson · Ulysses (1842)","level":"general","topics":["Tuổi tác","Công việc"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0258","text":"Some work of noble note may yet be done.","vi":"Ta vẫn còn có thể làm nên những việc đáng quý.","ex":"Ulysses believes, “Some work of noble note may yet be done.”","exVi":"Ông tin rằng mình vẫn còn cơ hội đóng góp điều có ý nghĩa.","src":"Alfred, Lord Tennyson · Ulysses (1842)","level":"general","topics":["Công việc","Mục tiêu"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0259","text":"To follow knowledge like a sinking star.","vi":"Mải miết theo đuổi tri thức như chạy theo một vì sao đang lặn.","ex":"Ulysses wants “to follow knowledge like a sinking star.”","exVi":"Ông hình dung việc học hỏi là hành trình theo đuổi một mục tiêu xa xôi.","src":"Alfred, Lord Tennyson · Ulysses (1842)","level":"general","topics":["Học tập","Khám phá"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0260","text":"Made weak by time and fate, but strong in will.","vi":"Dẫu thời gian và số phận làm suy yếu, ý chí vẫn mạnh mẽ.","ex":"Ulysses calls himself “Made weak by time and fate, but strong in will.”","exVi":"Ông thừa nhận tuổi tác nhưng vẫn giữ quyết tâm sống chủ động.","src":"Alfred, Lord Tennyson · Ulysses (1842)","level":"general","topics":["Ý chí","Tuổi tác"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0261","text":"Forlorn! the very word is like a bell.","vi":"Cô quạnh! Chỉ riêng từ ấy đã ngân lên như tiếng chuông.","ex":"Keats writes, “Forlorn! the very word is like a bell.”","exVi":"Từ “cô quạnh” kéo nhà thơ khỏi giấc mơ về tiếng chim sơn ca.","src":"John Keats · Ode to a Nightingale (1819)","level":"general","topics":["Cô đơn","Ngôn ngữ"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0262","text":"Was it a vision, or a waking dream?","vi":"Đó là một ảo ảnh hay một giấc mơ khi đang thức?","ex":"Keats asks, “Was it a vision, or a waking dream?”","exVi":"Nhà thơ tự hỏi trải nghiệm vừa qua là giấc mơ hay thực tại.","src":"John Keats · Ode to a Nightingale (1819)","level":"general","topics":["Tưởng tượng","Giấc mơ"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0263","text":"Season of mists and mellow fruitfulness","vi":"Mùa sương phủ và những trái cây chín ngọt dịu dàng.","ex":"Keats opens the poem with “Season of mists and mellow fruitfulness.”","exVi":"Câu thơ gợi ra mùa thu trù phú, dịu nhẹ và đầy sương.","src":"John Keats · To Autumn (1819)","level":"general","topics":["Thời tiết","Thiên nhiên"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0264","text":"Where are the songs of Spring? Ay, where are they?","vi":"Những khúc ca mùa xuân đâu rồi? Phải, chúng ở nơi nào?","ex":"Keats asks, “Where are the songs of Spring? Ay, where are they?”","exVi":"Bài thơ nhìn nhận mùa thu với vẻ đẹp riêng, không chỉ tiếc mùa xuân.","src":"John Keats · To Autumn (1819)","level":"general","topics":["Thiên nhiên","Thay đổi"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0265","text":"I fall upon the thorns of life! I bleed!","vi":"Tôi ngã xuống những gai nhọn của cuộc đời! Tôi đang chảy máu!","ex":"Shelley cries, “I fall upon the thorns of life! I bleed!”","exVi":"Nhà thơ dùng hình ảnh gai nhọn để diễn tả nỗi đau và sự kiệt sức.","src":"Percy Bysshe Shelley · Ode to the West Wind (1819)","level":"general","topics":["Khó khăn","Cảm xúc"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0266","text":"Nothing in the world is single; all things by a law divine","vi":"Không điều gì trên đời tồn tại riêng lẻ; vạn vật gắn kết theo quy luật thiêng liêng.","ex":"Shelley writes, “Nothing in the world is single; all things by a law divine.”","exVi":"Bài thơ nhấn mạnh sự gắn bó giữa con người với thế giới tự nhiên.","src":"Percy Bysshe Shelley · Love’s Philosophy (1819)","level":"general","topics":["Thiên nhiên","Kết nối"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0267","text":"The desire of the moth for the star, of the night for the morrow.","vi":"Khát vọng của con thiêu thân hướng về vì sao, của đêm mong chờ ngày mai.","ex":"Shelley compares longing to “The desire of the moth for the star, of the night for the morrow.”","exVi":"Shelley ví nỗi khao khát tình yêu với những lực hút trong tự nhiên.","src":"Percy Bysshe Shelley · Love’s Philosophy (1819)","level":"general","topics":["Tình yêu","Khát vọng"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0268","text":"Music, when soft voices die, vibrates in the memory.","vi":"Khi những giọng nói dịu dàng lặng đi, âm nhạc vẫn ngân trong ký ức.","ex":"Shelley writes, “Music, when soft voices die, vibrates in the memory.”","exVi":"Bài thơ gợi cách âm thanh và kỷ niệm còn ở lại sau chia xa.","src":"Percy Bysshe Shelley · To — (1824)","level":"general","topics":["Âm nhạc","Ký ức"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0269","text":"Tell me not, in mournful numbers, Life is but an empty dream!","vi":"Đừng nói với tôi bằng lời bi ai rằng cuộc đời chỉ là giấc mộng trống rỗng!","ex":"Longfellow begins, “Tell me not, in mournful numbers, Life is but an empty dream!”","exVi":"Bài thơ phản bác thái độ bi quan và khuyên người đọc sống có mục đích.","src":"Henry Wadsworth Longfellow · A Psalm of Life (1838)","level":"general","topics":["Sống tích cực","Mục tiêu"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0270","text":"The road of excess leads to the palace of wisdom.","vi":"Con đường trải nghiệm đến tận cùng có thể dẫn tới sự thấu hiểu.","ex":"The road of excess leads to the palace of wisdom.","exVi":"Blake dùng hình ảnh một con đường để nói về trải nghiệm và tri thức.","src":"William Blake · The Marriage of Heaven and Hell (1793)","level":"general","topics":["Học tập","Trải nghiệm"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0271","text":"Exuberance is Beauty.","vi":"Sự sống động đầy nhiệt huyết chính là vẻ đẹp.","ex":"Exuberance is Beauty.","exVi":"Blake xem sức sống dồi dào là một nét đẹp đáng trân trọng.","src":"William Blake · The Marriage of Heaven and Hell (1793)","level":"general","topics":["Vẻ đẹp","Cảm xúc"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0272","text":"The cut worm forgives the plough.","vi":"Con giun bị lưỡi cày làm đứt vẫn được ví như biết tha thứ.","ex":"The cut worm forgives the plough.","exVi":"Hình ảnh chiếc cày và con giun gợi suy ngẫm về tổn thương và tha thứ.","src":"William Blake · The Marriage of Heaven and Hell (1793)","level":"general","topics":["Tha thứ","Thiên nhiên"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0273","text":"The tygers of wrath are wiser than the horses of instruction.","vi":"Những con hổ của cơn giận còn khôn ngoan hơn những con ngựa của sự răn dạy.","ex":"The tygers of wrath are wiser than the horses of instruction.","exVi":"Blake đặt bản năng mạnh mẽ cạnh những bài học khuôn phép.","src":"William Blake · The Marriage of Heaven and Hell (1793)","level":"general","topics":["Cảm xúc","Học tập"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0274","text":"Improvement makes straight roads; but the crooked roads without Improvement are roads of Genius.","vi":"Sự cải tiến tạo ra những con đường thẳng; còn đường quanh co không cải tiến lại có thể là lối đi của thiên tài.","ex":"Improvement makes straight roads; but the crooked roads without Improvement are roads of Genius.","exVi":"Blake ví sự sáng tạo với lối đi không theo khuôn mẫu có sẵn.","src":"William Blake · The Marriage of Heaven and Hell (1793)","level":"general","topics":["Sáng tạo","Thay đổi"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0275","text":"The music in my heart I bore, long after it was heard no more.","vi":"Giai điệu ấy vẫn ở trong tim tôi rất lâu sau khi không còn được nghe nữa.","ex":"The music in my heart I bore, long after it was heard no more.","exVi":"Người kể vẫn mang theo dư âm của bài hát sau khi tiếng hát đã xa.","src":"William Wordsworth · The Solitary Reaper (1807)","level":"general","topics":["Âm nhạc","Ký ức"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0276","text":"My heart leaps up when I behold a rainbow in the sky.","vi":"Tim tôi rộn lên mỗi khi nhìn thấy cầu vồng trên bầu trời.","ex":"My heart leaps up when I behold a rainbow in the sky.","exVi":"Nhà thơ diễn tả niềm vui giản dị khi bắt gặp cầu vồng.","src":"William Wordsworth · My Heart Leaps Up (1807)","level":"general","topics":["Thiên nhiên","Cảm xúc"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0277","text":"The sounding cataract haunted me like a passion.","vi":"Tiếng thác vang vọng ám ảnh tôi như một niềm say mê.","ex":"The sounding cataract haunted me like a passion.","exVi":"Wordsworth nhớ lại cảm giác mãnh liệt trước cảnh thác nước khi còn trẻ.","src":"William Wordsworth · Lines Composed a Few Miles above Tintern Abbey (1798)","level":"general","topics":["Thiên nhiên","Tuổi trẻ"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0278","text":"To me the meanest flower that blows can give thoughts that do often lie too deep for tears.","vi":"Với tôi, ngay cả bông hoa bình thường nhất cũng gợi nên những suy tư sâu đến mức chẳng thể khóc thành lời.","ex":"To me the meanest flower that blows can give thoughts that do often lie too deep for tears.","exVi":"Một bông hoa nhỏ bé cũng có thể khơi lên cảm xúc vượt ngoài lời nói.","src":"William Wordsworth · Ode: Intimations of Immortality (1807)","level":"general","topics":["Thiên nhiên","Suy ngẫm"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0279","text":"Though inland far we be, our souls have sight of that immortal sea.","vi":"Dẫu ở sâu trong đất liền, tâm hồn ta vẫn nhìn thấy biển cả bất diệt ấy.","ex":"Though inland far we be, our souls have sight of that immortal sea.","exVi":"Nhà thơ gợi cảm giác tâm hồn vẫn hướng về một cội nguồn rộng lớn.","src":"William Wordsworth · Ode: Intimations of Immortality (1807)","level":"general","topics":["Tâm hồn","Thiên nhiên"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0280","text":"Trailing clouds of glory do we come.","vi":"Chúng ta đến với cuộc đời như mang theo những đám mây vinh quang.","ex":"Trailing clouds of glory do we come.","exVi":"Wordsworth hình dung tuổi thơ như vẫn còn gần với một thế giới thiêng liêng.","src":"William Wordsworth · Ode: Intimations of Immortality (1807)","level":"general","topics":["Tuổi thơ","Tâm hồn"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0281","text":"’Tis better to have loved and lost than never to have loved at all.","vi":"Đã từng yêu rồi mất đi vẫn tốt hơn là chưa từng yêu bao giờ.","ex":"’Tis better to have loved and lost than never to have loved at all.","exVi":"Câu thơ cho rằng trải nghiệm tình yêu vẫn có giá trị dù kết thúc bằng mất mát.","src":"Alfred, Lord Tennyson · In Memoriam A.H.H. (1850)","level":"general","topics":["Tình yêu","Mất mát"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0282","text":"I hold it true, whate’er befall.","vi":"Dù điều gì xảy ra, tôi vẫn tin điều ấy là đúng.","ex":"I hold it true, whate’er befall.","exVi":"Tennyson bày tỏ niềm tin bền vững giữa nỗi đau và bất định.","src":"Alfred, Lord Tennyson · In Memoriam A.H.H. (1850)","level":"general","topics":["Niềm tin","Khó khăn"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0283","text":"Ring out, wild bells, to the wild sky.","vi":"Hãy ngân vang, những hồi chuông tự do, giữa bầu trời rộng mở.","ex":"Ring out, wild bells, to the wild sky.","exVi":"Bài thơ kêu gọi buông bỏ điều cũ và chào đón một khởi đầu mới.","src":"Alfred, Lord Tennyson · In Memoriam A.H.H. (1850)","level":"general","topics":["Thay đổi","Hy vọng"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0284","text":"Nature, red in tooth and claw.","vi":"Thiên nhiên đỏ màu máu nơi nanh vuốt.","ex":"Nature, red in tooth and claw.","exVi":"Tennyson mô tả thiên nhiên như một thế lực khắc nghiệt trong cuộc đấu tranh sinh tồn.","src":"Alfred, Lord Tennyson · In Memoriam A.H.H. (1850)","level":"general","topics":["Thiên nhiên","Sinh tồn"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0285","text":"Call me Ishmael.","vi":"Cứ gọi tôi là Ishmael.","ex":"Call me Ishmael.","exVi":"Người kể chuyện mở đầu hành trình bằng cách tự giới thiệu ngắn gọn.","src":"Herman Melville · Moby-Dick; or, The Whale (1851)","level":"general","topics":["Du lịch","Kể chuyện"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0286","text":"All visible objects, man, are but as pasteboard masks.","vi":"Hỡi con người, mọi vật nhìn thấy được chỉ như những chiếc mặt nạ bằng bìa.","ex":"All visible objects, man, are but as pasteboard masks.","exVi":"Melville gợi ý rằng vẻ ngoài có thể che giấu những ý nghĩa sâu hơn.","src":"Herman Melville · Moby-Dick; or, The Whale (1851)","level":"general","topics":["Nhận thức","Suy ngẫm"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0287","text":"Towards thee I roll, thou all-destroying but unconquering whale!","vi":"Ta lao về phía ngươi, hỡi con cá voi hủy diệt mọi thứ nhưng không thể bị khuất phục!","ex":"Towards thee I roll, thou all-destroying but unconquering whale!","exVi":"Ahab đối mặt với con cá voi bằng quyết tâm và cơn thịnh nộ dữ dội.","src":"Herman Melville · Moby-Dick; or, The Whale (1851)","level":"general","topics":["Đối đầu","Thiên nhiên"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0288","text":"From hell's heart I stab at thee; for hate's sake I spit my last breath at thee.","vi":"Từ tận đáy địa ngục, ta đâm vào ngươi; vì thù hận, ta trút hơi thở cuối cùng lên ngươi.","ex":"From hell's heart I stab at thee; for hate's sake I spit my last breath at thee.","exVi":"Ahab dồn toàn bộ thù hận vào lời đối đầu cuối cùng với cá voi trắng.","src":"Herman Melville · Moby-Dick; or, The Whale (1851)","level":"general","topics":["Thù hận","Đối đầu"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0289","text":"There is all the difference in the world between paying and being paid.","vi":"Có sự khác biệt lớn giữa việc trả tiền và được trả tiền.","ex":"There is all the difference in the world between paying and being paid.","exVi":"Ishmael hài hước nhận xét niềm vui khi được nhận tiền công.","src":"Herman Melville · Moby-Dick; or, The Whale (1851)","level":"general","topics":["Tiền bạc","Công việc"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0290","text":"Ah! how cheerfully we consign ourselves to perdition!","vi":"Ôi, chúng ta sẵn lòng tự đẩy mình vào cảnh khốn cùng biết bao!","ex":"Ah! how cheerfully we consign ourselves to perdition!","exVi":"Ishmael mỉa mai cách con người tự nguyện lao vào những điều bất lợi.","src":"Herman Melville · Moby-Dick; or, The Whale (1851)","level":"general","topics":["Thói quen","Suy ngẫm"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0291","text":"A whale-ship was my Yale College and my Harvard.","vi":"Con tàu săn cá voi chính là trường Yale và Harvard của tôi.","ex":"A whale-ship was my Yale College and my Harvard.","exVi":"Ishmael xem những chuyến đi biển như quãng đời học hỏi của mình.","src":"Herman Melville · Moby-Dick; or, The Whale (1851)","level":"general","topics":["Học tập","Du lịch"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0292","text":"Lives of great men all remind us.","vi":"Cuộc đời những người vĩ đại nhắc nhở chúng ta nhiều điều.","ex":"Lives of great men all remind us.","exVi":"Longfellow mở một ý thơ về cách gương người đi trước truyền cảm hứng.","src":"Henry Wadsworth Longfellow · A Psalm of Life (1838)","level":"general","topics":["Cảm hứng","Lịch sử"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0293","text":"We can make our lives sublime.","vi":"Chúng ta có thể khiến cuộc đời mình trở nên cao đẹp.","ex":"We can make our lives sublime.","exVi":"Nhà thơ tin rằng mỗi người đều có thể sống một cuộc đời có ý nghĩa.","src":"Henry Wadsworth Longfellow · A Psalm of Life (1838)","level":"general","topics":["Mục tiêu","Sống tích cực"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0294","text":"Footprints on the sands of time.","vi":"Những dấu chân còn in trên bãi cát thời gian.","ex":"Footprints on the sands of time.","exVi":"Hình ảnh dấu chân gợi những việc làm có thể để lại ảnh hưởng lâu dài.","src":"Henry Wadsworth Longfellow · A Psalm of Life (1838)","level":"general","topics":["Thời gian","Di sản"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0295","text":"Theirs not to reason why, theirs but to do and die.","vi":"Họ không có quyền hỏi tại sao; nhiệm vụ của họ là hành động, dù phải hy sinh.","ex":"Theirs not to reason why, theirs but to do and die.","exVi":"Tennyson mô tả những kỵ binh thực hiện mệnh lệnh giữa trận chiến.","src":"Alfred, Lord Tennyson · The Charge of the Light Brigade (1854)","level":"general","topics":["Trách nhiệm","Can đảm"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0296","text":"I wanted to live deep and suck out all the marrow of life.","vi":"Tôi muốn sống sâu sắc và tận hưởng trọn vẹn tinh túy của cuộc đời.","ex":"I wanted to live deep and suck out all the marrow of life.","exVi":"Thoreau nói về mong muốn trải nghiệm cuộc sống một cách trọn vẹn.","src":"Henry David Thoreau · Walden (1854)","level":"general","topics":["Sống tích cực","Trải nghiệm"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0297","text":"Our life is frittered away by detail.","vi":"Cuộc đời chúng ta bị tiêu hao dần bởi những tiểu tiết.","ex":"Our life is frittered away by detail.","exVi":"Thoreau cảnh báo rằng quá nhiều việc vụn vặt có thể làm ta mất tập trung.","src":"Henry David Thoreau · Walden (1854)","level":"general","topics":["Thời gian","Thói quen"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0298","text":"Time is but the stream I go a-fishing in.","vi":"Thời gian chỉ là dòng suối nơi tôi thả câu.","ex":"Time is but the stream I go a-fishing in.","exVi":"Thoreau ví thời gian như dòng nước để suy ngẫm về cách mình sống.","src":"Henry David Thoreau · Walden (1854)","level":"general","topics":["Thời gian","Suy ngẫm"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0299","text":"Simplicity, simplicity, simplicity!","vi":"Đơn giản thôi, đơn giản thôi, hãy sống thật đơn giản!","ex":"Simplicity, simplicity, simplicity!","exVi":"Thoreau khuyên giảm bớt những điều phức tạp trong đời sống thường ngày.","src":"Henry David Thoreau · Walden (1854)","level":"general","topics":["Lối sống","Thói quen"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"qte-0300","text":"The still, sad music of humanity.","vi":"Khúc nhạc trầm buồn, lặng lẽ của nhân loại.","ex":"The still, sad music of humanity.","exVi":"Wordsworth gọi nỗi buồn của con người là một khúc nhạc lặng lẽ.","src":"William Wordsworth · Lines Composed a Few Miles above Tintern Abbey (1798)","level":"general","topics":["Cảm xúc","Nhân loại"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false}]};
